import React, { useRef, useState } from 'react';
import { View, PanResponder, Animated, StyleSheet } from 'react-native';
import TableGraphic from './TableGraphic';
import { Table } from '../types';

interface DraggableTableProps {
    table: Table;
    onDragEnd: (id: string, x: number, y: number) => void;
    scale?: number;
}

export default function DraggableTable({ table, onDragEnd, scale = 1 }: DraggableTableProps) {
    // Current position
    const pan = useRef(new Animated.ValueXY({ x: table.position_x, y: table.position_y })).current;
    const [isDragging, setIsDragging] = useState(false);

    // Sync internal pan state if props change (useful for resets or initial layout distribution)
    React.useEffect(() => {
        pan.setValue({ x: table.position_x, y: table.position_y });
    }, [table.position_x, table.position_y]);

    const panResponder = useRef(
        PanResponder.create({
            onStartShouldSetPanResponder: () => true,
            onPanResponderGrant: () => {
                setIsDragging(true);
                // Set offset to current value to prevent jumping
                // @ts-ignore
                pan.setOffset({
                    // @ts-ignore
                    x: pan.x._value,
                    // @ts-ignore
                    y: pan.y._value
                });
                pan.setValue({ x: 0, y: 0 });
            },
            onPanResponderMove: Animated.event(
                [null, { dx: pan.x, dy: pan.y }],
                { useNativeDriver: false }
            ),
            onPanResponderRelease: () => {
                setIsDragging(false);
                pan.flattenOffset();

                // Get final values
                // @ts-ignore
                const x = pan.x._value;
                // @ts-ignore
                const y = pan.y._value;

                onDragEnd(table.id, x, y);
            }
        })
    ).current;

    return (
        <Animated.View
            {...panResponder.panHandlers}
            style={[
                styles.draggable,
                {
                    transform: [{ translateX: pan.x }, { translateY: pan.y }, { scale: isDragging ? 1.1 : 1 }],
                    opacity: isDragging ? 0.8 : 1,
                    zIndex: isDragging ? 1000 : 1
                }
            ]}
        >
            <TableGraphic
                shape={table.shape}
                seats={table.seats}
                status={table.status === 'Pagamento' ? 'Pagando' : (table.status as any) || 'Livre'}
                size={60} // Fixed size for editor
                tableNumber={table.number}
            />
        </Animated.View>
    );
}

const styles = StyleSheet.create({
    draggable: {
        position: 'absolute',
        top: 0,
        left: 0,
    }
});

import React from 'react';
import { View, Text, StyleSheet, ScrollView, TouchableOpacity, Alert } from 'react-native';

interface Props {
  children: React.ReactNode;
}

interface State {
  hasError: boolean;
  error: Error | null;
  errorInfo: any;
}

export class ErrorBoundary extends React.Component<Props, State> {
  constructor(props: Props) {
    super(props);
    this.state = { hasError: false, error: null, errorInfo: null };
  }

  static getDerivedStateFromError(error: Error) {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, errorInfo: any) {
    console.error("ErrorBoundary caught an error", error, errorInfo);
    this.setState({ errorInfo });
  }

  render() {
    if (this.state.hasError) {
      return (
        <View style={styles.container}>
          <ScrollView contentContainerStyle={styles.scroll}>
            <Text style={styles.title}>💥 Ops! Ocorreu um erro.</Text>
            <Text style={styles.subtitle}>O aplicativo encontrou um erro inesperado.</Text>

            <View style={styles.box}>
              <Text style={styles.errorType}>{this.state.error?.name}</Text>
              <Text style={styles.errorMessage}>{this.state.error?.message}</Text>
            </View>

            {this.state.errorInfo && (
                <Text style={styles.stackTrace}>
                    {this.state.errorInfo.componentStack}
                </Text>
            )}

            <TouchableOpacity 
                style={styles.button}
                onPress={() => this.setState({ hasError: false, error: null })}
            >
                <Text style={styles.buttonText}>Tentar Novamente</Text>
            </TouchableOpacity>
          </ScrollView>
        </View>
      );
    }

    return this.props.children;
  }
}

