     // Suppress console error for this test
     const consoleSpy = jest.spyOn(console, 'error').mockImplementation(() => {});

     render(
       <LazyLoadErrorBoundary>
         <LazyLoadWrapper>
           <ErrorComponent />
         </LazyLoadWrapper>
       </LazyLoadErrorBoundary>
     );

     await waitFor(() => expect(screen.getByText('Erro ao carregar')).toBeTruthy());
     
     consoleSpy.mockRestore();
  });

  it('createLazyScreen should return a wrapped component', async () => {
