import React from 'react';
import { render, waitFor, act } from '@testing-library/react-native';
import OptimizedImage from '../OptimizedImage';
import { ActivityIndicator, Image } from 'react-native';

describe('OptimizedImage', () => {
  beforeEach(() => {
    jest.useFakeTimers();
  });

