  });

  it('should render loading indicator initially', () => {
    const { getByTestId, UNSAFE_getByType } = render(
      <OptimizedImage uri="https://example.com/image.jpg" />
    );
    // Assuming ActivityIndicator is rendered
    expect(UNSAFE_getByType(ActivityIndicator)).toBeTruthy();
  });

  it('should render image source when loaded', async () => {
    const { UNSAFE_getByType } = render(
      <OptimizedImage uri="https://example.com/image.jpg" lazy={false} />
    );

    const image = UNSAFE_getByType(Image);
    expect(image.props.source).toEqual({ uri: 'https://example.com/image.jpg', cache: 'default' });
  });

  it('should handle lazy loading', async () => {
    const { UNSAFE_getByType } = render(
      <OptimizedImage uri="https://example.com/lazy.jpg" lazy={true} />
    );

    // Should ideally show placeholder or nothing if not loaded
    // Component logic: runs timer for 100ms then sets shouldLoad=true
    
    act(() => {
      jest.advanceTimersByTime(150);
    });

    const image = UNSAFE_getByType(Image);
    expect(image.props.source).toEqual({ uri: 'https://example.com/lazy.jpg', cache: 'default' });
  });

