    menuItemText: { fontSize: 16, color: colors.text },
    menuItemPrice: { fontWeight: 'bold', color: colors.success },

    cart: { backgroundColor: '#E8F5E9', padding: 15, borderRadius: 10, marginBottom: 20 },
