                  // Aplica formatação enquanto digita
                  let formatted = limited;
                  if (limited.length > 3) {
                    formatted = limited.substring(0, 3) + '.' + limited.substring(3);
                  }
                  if (limited.length > 6) {
                    formatted = limited.substring(0, 3) + '.' + limited.substring(3, 6) + '.' + limited.substring(6);
