interface Props {
  onClose?: () => void;
}

export default function GerenciarFornecedoresScreen({ onClose }: Props) {
    const { user } = useAuth();
    const [fornecedores, setFornecedores] = useState<any[]>([]);
    const [loading, setLoading] = useState(false);
    const [modalVisible, setModalVisible] = useState(false);

    // Form states
    const [editingId, setEditingId] = useState<string | null>(null);
    const [nome, setNome] = useState('');
    const [cnpj, setCnpj] = useState('');
    const [contato, setContato] = useState(''); // Usado como Telefone
    const [email, setEmail] = useState('');

    useEffect(() => {
        carregarFornecedores();
    }, []);

    const carregarFornecedores = async () => {
        // @ts-ignore
        if (!user?.companyId) return;

        try {
            setLoading(true);
            const { data, error } = await supabase
                .from('suppliers')
                .select('*')
                .eq('company_id', user.companyId)
                .order('nome', { ascending: true });

            if (error) throw error;

            const lista = (data || []).map(item => ({ id: item.id, ...item }));
            setFornecedores(lista);
        } catch (error) {
            console.error('Erro ao carregar fornecedores:', error);
            Alert.alert('Erro', 'Não foi possível carregar os fornecedores');
        } finally {
            setLoading(false);
        }
    };

    const limparForm = () => {
        setEditingId(null);
        setNome('');
        setCnpj('');
        setContato('');
        setEmail('');
    };

    const abrirModal = (fornecedor: any = null) => {
        if (fornecedor) {
            setEditingId(fornecedor.id);
            setNome(fornecedor.nome);
            setCnpj(fornecedor.cnpj || '');
            setContato(fornecedor.contato || '');
            setEmail(fornecedor.email || '');
        } else {
            limparForm();
        }
        setModalVisible(true);
    };

    const handleChangeCnpj = (text: string) => {
        const masked = maskCNPJ(text);
        setCnpj(masked);
    };

    const handleChangePhone = (text: string) => {
        const masked = maskPhone(text);
        setContato(masked);
    };

    const salvarFornecedor = async () => {
        if (!nome.trim()) {
            Alert.alert('Atenção', 'Nome do fornecedor é obrigatório');
            return;
        }

        // Validação CNPJ
        if (cnpj && !validateCNPJ(cnpj)) {
            Alert.alert('Erro', 'CNPJ inválido');
            return;
        }

        // Validação Email
        if (email && !validateEmail(email)) {
            Alert.alert('Erro', 'Email inválido');
            return;
        }

        try {
            setLoading(true);
            const dados = {
                nome: nome.trim(),
                cnpj: cnpj.trim(),
                contato: contato.trim(),
                email: email.trim(),
                company_id: user?.companyId,
                updated_at: new Date().toISOString()
            };

            if (editingId) {
                const { error } = await supabase
                    .from('suppliers')
                    .update(dados)
                    .eq('id', editingId);

                if (error) throw error;
                Alert.alert('Sucesso', 'Fornecedor atualizado!');
            } else {
                const { error } = await supabase
                    .from('suppliers')
                    .insert({
                        ...dados,
                        created_at: new Date().toISOString()
                    });

                if (error) throw error;
                Alert.alert('Sucesso', 'Fornecedor cadastrado!');
            }

            setModalVisible(false);
            carregarFornecedores();
        } catch (error) {
            console.error('Erro ao salvar:', error);
            Alert.alert('Erro', 'Falha ao salvar fornecedor');
        } finally {
            setLoading(false);
        }
    };

    const deletarFornecedor = (item: any) => {
        Alert.alert(
            'Excluir Fornecedor',
            `Deseja realmente excluir "${item.nome}"?`,
            [
                { text: 'Cancelar', style: 'cancel' },
                {
                    text: 'Excluir',
                    style: 'destructive',
                    onPress: async () => {
                        try {
                            setLoading(true);
                            const { error } = await supabase
                                .from('suppliers')
                                .delete()
                                .eq('id', item.id);

                            if (error) throw error;
                            carregarFornecedores();
                        } catch (error) {
                            Alert.alert('Erro', 'Não foi possível excluir');
                        } finally {
                            setLoading(false);
                        }
                    }
                }
            ]
        );
    };

    return (
        <ScreenScaffold
            title="Fornecedores"
            leftAction={{ label: 'Voltar', onPress: onClose ?? (() => {}) }}
        >
            <View style={styles.content}>
                <TouchableOpacity style={styles.addBtn} onPress={() => abrirModal()}>
                    <Text style={styles.addBtnText}>+ Novo Fornecedor</Text>
                </TouchableOpacity>

                {loading && !modalVisible ? (
                    <ActivityIndicator size="large" color="#8B2F2F" style={{ marginTop: 20 }} />
                ) : (
                    <ScrollView contentContainerStyle={styles.list}>
                        {fornecedores.length === 0 ? (
                            <Text style={styles.emptyText}>Nenhum fornecedor cadastrado</Text>
                        ) : (
                            fornecedores.map(item => (
                                <View key={item.id} style={styles.card}>
                                    <View style={styles.cardInfo}>
                                        <Text style={styles.cardTitle}>{item.nome}</Text>
                                        {!!item.cnpj && <Text style={styles.cardSubtitle}>CNPJ: {item.cnpj}</Text>}
                                        {!!item.contato && <Text style={styles.cardSubtitle}>📞 {item.contato}</Text>}
                                        {!!item.email && <Text style={styles.cardSubtitle}>✉️ {item.email}</Text>}
                                    </View>
                                    <View style={styles.cardActions}>
                                        <TouchableOpacity onPress={() => abrirModal(item)} style={styles.actionBtn}>
                                            <Ionicons name="pencil" size={20} color="#B45309" />
                                        </TouchableOpacity>
                                        <TouchableOpacity onPress={() => deletarFornecedor(item)} style={styles.actionBtn}>
                                            <Ionicons name="trash" size={20} color="#FF6B6B" />
                                        </TouchableOpacity>
                                    </View>
                                </View>
                            ))
                        )}
                    </ScrollView>
                )}
            </View>

            <Modal visible={modalVisible} animationType="slide" transparent={true}>
                <View style={styles.modalOverlay}>
                    <View style={styles.modalContent}>
                        <Text style={styles.modalTitle}>
                            {editingId ? 'Editar Fornecedor' : 'Novo Fornecedor'}
                        </Text>

                        <TextInput
                            style={styles.input}
                            placeholder="Nome da Empresa *"
                            value={nome}
                            onChangeText={setNome}
                            placeholderTextColor="#999"
                        />

                        <TextInput
                            style={styles.input}
                            placeholder="CNPJ"
                            value={cnpj}
                            onChangeText={handleChangeCnpj}
                            keyboardType="numeric"
                            placeholderTextColor="#999"
                            maxLength={18}
                        />

                        <TextInput
                            style={styles.input}
                            placeholder="Celular (XX) X XXXX-XXXX"
                            value={contato}
                            onChangeText={handleChangePhone}
                            keyboardType="phone-pad"
                            placeholderTextColor="#999"
                            maxLength={15}
                        />

                        <TextInput
                            style={styles.input}
                            placeholder="Email"
                            value={email}
                            onChangeText={setEmail}
                            keyboardType="email-address"
                            autoCapitalize="none"
                            placeholderTextColor="#999"
                        />

                        <View style={styles.modalButtons}>
                            <TouchableOpacity
                                style={[styles.modalBtn, styles.cancelBtn]}
                                onPress={() => setModalVisible(false)}
                            >
                                <Text style={styles.cancelBtnText}>Cancelar</Text>
                            </TouchableOpacity>

                            <TouchableOpacity
                                style={[styles.modalBtn, styles.saveBtn]}
                                onPress={salvarFornecedor}
                            >
                                <Text style={styles.saveBtnText}>Salvar</Text>
                            </TouchableOpacity>
                        </View>
                    </View>
                </View>
            </Modal>
        </ScreenScaffold>
    );
}

