/**
 * BiometricAuthService - Biometric Authentication Service
 * Implements fingerprint and face recognition with secure token validation
 */

import * as LocalAuthentication from 'expo-local-authentication';
import * as SecureStore from 'expo-secure-store';
import { Platform } from 'react-native';
import AsyncStorage from '@react-native-async-storage/async-storage';

interface BiometricEnrollmentData {
  userId: string;
  enrolledAt: Date;
  biometricType: 'fingerprint' | 'face' | 'iris' | 'unknown';
  deviceId: string;
  lastUsedAt: Date | null;
}

interface BiometricAuthResult {
  success: boolean;
  biometricType?: string;
  error?: string;
  fallbackToPassword?: boolean;
}

class BiometricAuthService {
  private readonly ENROLLMENT_KEY = 'biometric_enrollment';
  private readonly SESSION_TOKEN_KEY = 'biometric_session_token';
  private readonly CREDENTIALS_KEY = 'biometric_credentials';
  private readonly LAST_USER_KEY = 'biometric_last_uid';
  private readonly SESSION_DURATION_MS = 30 * 24 * 60 * 60 * 1000; // 30 days

  /**
   * Check if device supports biometric authentication
   */
  async isSupported(): Promise<boolean> {
    try {
      const compatible = await LocalAuthentication.hasHardwareAsync();
      return compatible;
    } catch (error) {
      console.error('[BiometricAuth] Error checking hardware support:', error);
      return false;
    }
  }

  /**
   * Check if user has enrolled biometrics on device
   */
  async hasEnrolledBiometrics(): Promise<boolean> {
    try {
      const enrolled = await LocalAuthentication.isEnrolledAsync();
      return enrolled;
    } catch (error) {
      console.error('[BiometricAuth] Error checking enrollment:', error);
      return false;
    }
  }

  /**
   * Get available biometric types on device
   */
  async getAvailableBiometricTypes(): Promise<string[]> {
    try {
      const types = await LocalAuthentication.supportedAuthenticationTypesAsync();

      const typeNames = types.map(type => {
        switch (type) {
          case LocalAuthentication.AuthenticationType.FINGERPRINT:
            return 'fingerprint';
          case LocalAuthentication.AuthenticationType.FACIAL_RECOGNITION:
            return 'face';
          case LocalAuthentication.AuthenticationType.IRIS:
            return 'iris';
          default:
            return 'unknown';
        }
      });

      return typeNames;
    } catch (error) {
      console.error('[BiometricAuth] Error getting biometric types:', error);
      return [];
    }
  }

  /**
   * Get user-friendly name for biometric type
   */
  getBiometricTypeName(types: string[]): string {
    if (types.includes('face')) {
      return Platform.OS === 'ios' ? 'Face ID' : 'Reconhecimento Facial';
    }
    if (types.includes('fingerprint')) {
      return Platform.OS === 'ios' ? 'Touch ID' : 'Impressão Digital';
    }
    if (types.includes('iris')) {
      return 'Reconhecimento de Íris';
    }
    return 'Biometria';
  }

  /**
   * Check if biometric authentication is enabled for user
   */
  async isEnabledForUser(userId: string): Promise<boolean> {
    try {
      const enrollmentData = await this.getEnrollmentData(userId);
      return enrollmentData !== null;
    } catch (error) {
      console.error('[BiometricAuth] Error checking if enabled:', error);
      return false;
    }
  }

  /**
   * Enroll user for biometric authentication
   */
  /**
   * Enroll user for biometric authentication
   */
  async enrollUser(userId: string, deviceId: string, email?: string, password?: string): Promise<void> {
    try {
      // Verify device supports biometrics
      const isSupported = await this.isSupported();
      if (!isSupported) {
        throw new Error('Dispositivo não suporta autenticação biométrica');
      }

      // Verify user has enrolled biometrics
      const hasEnrolled = await this.hasEnrolledBiometrics();
      if (!hasEnrolled) {
        throw new Error('Nenhuma biometria cadastrada no dispositivo');
      }

      // Get biometric types
      const types = await this.getAvailableBiometricTypes();
      const biometricType = types[0] || 'unknown';

      // Store enrollment data
      const enrollmentData: BiometricEnrollmentData = {
        userId,
        enrolledAt: new Date(),
        biometricType: biometricType as any,
        deviceId,
        lastUsedAt: null,
      };

      await SecureStore.setItemAsync(
        `${this.ENROLLMENT_KEY}_${userId}`,
        JSON.stringify(enrollmentData)
      );

      // Store credentials if provided
      if (email && password) {
        await this.storeCredentials(userId, email, password);
      }

      // Mark as last user
      await AsyncStorage.setItem(this.LAST_USER_KEY, userId);

      console.log('[BiometricAuth] User enrolled successfully');
    } catch (error) {
      console.error('[BiometricAuth] Error enrolling user:', error);
      throw error;
    }
  }

  /**
   * Unenroll user from biometric authentication
   */
  /**
   * Unenroll user from biometric authentication
   */
  async unenrollUser(userId: string): Promise<void> {
    try {
      await SecureStore.deleteItemAsync(`${this.ENROLLMENT_KEY}_${userId}`);
      await SecureStore.deleteItemAsync(`${this.SESSION_TOKEN_KEY}_${userId}`);
      await SecureStore.deleteItemAsync(`${this.CREDENTIALS_KEY}_${userId}`);

      const lastUser = await AsyncStorage.getItem(this.LAST_USER_KEY);
      if (lastUser === userId) {
         await AsyncStorage.removeItem(this.LAST_USER_KEY);
      }

      console.log('[BiometricAuth] User unenrolled successfully');
    } catch (error) {
      console.error('[BiometricAuth] Error unenrolling user:', error);
      throw error;
    }
  }

  /**
   * Authenticate user with biometrics
   */
  async authenticate(
    userId: string,
    promptMessage?: string
  ): Promise<BiometricAuthResult> {
    try {
      // Check if user is enrolled
      const isEnabled = await this.isEnabledForUser(userId);
      if (!isEnabled) {
        return {
          success: false,
          error: 'Autenticação biométrica não está habilitada',
          fallbackToPassword: true,
        };
      }

      // Check if device supports biometrics
      const isSupported = await this.isSupported();
      if (!isSupported) {
        return {
          success: false,
          error: 'Dispositivo não suporta autenticação biométrica',
          fallbackToPassword: true,
        };
      }

      // Check if user has enrolled biometrics
      const hasEnrolled = await this.hasEnrolledBiometrics();
      if (!hasEnrolled) {
        return {
          success: false,
          error: 'Nenhuma biometria cadastrada no dispositivo',
          fallbackToPassword: true,
        };
      }

      // Get biometric types for prompt
      const types = await this.getAvailableBiometricTypes();
      const biometricName = this.getBiometricTypeName(types);

      // Sanitize prompt message
      let safePromptMessage = promptMessage || `Autentique com ${biometricName}`;
      // Remove any non-printable characters and limit length
      safePromptMessage = safePromptMessage.replace(/[^\x20-\x7E]/g, '').substring(0, 100);

      // Perform biometric authentication
      const result = await LocalAuthentication.authenticateAsync({
        promptMessage: safePromptMessage,
        cancelLabel: 'Cancelar',
        fallbackLabel: 'Usar senha',
        disableDeviceFallback: false,
      });

      if (result.success) {
        // Update last used timestamp
        await this.updateLastUsed(userId);

        // Validate session token
        const isTokenValid = await this.validateSessionToken(userId);

        return {
          success: true,
          biometricType: types[0],
        };
      } else {
        // Authentication failed or cancelled
        let error = 'Autenticação biométrica falhou';
        let fallbackToPassword = false;

        if (result.error === 'user_cancel') {
          error = 'Autenticação cancelada pelo usuário';
          fallbackToPassword = true;
        } else if (result.error === 'user_fallback') {
          error = 'Usuário optou por usar senha';
          fallbackToPassword = true;
        } else if (result.error === 'lockout') {
          error = 'Muitas tentativas falhadas. Tente novamente mais tarde.';
          fallbackToPassword = true;
        } else if (result.error === 'not_enrolled') {
          error = 'Nenhuma biometria cadastrada no dispositivo';
          fallbackToPassword = true;
        }

        return {
          success: false,
          error,
          fallbackToPassword,
        };
      }
    } catch (error: any) {
      console.error('[BiometricAuth] Authentication error:', error);
      return {
        success: false,
        error: error.message || 'Erro ao autenticar com biometria',
        fallbackToPassword: true,
      };
    }
  }

  /**
   * Verify biometric ownership (for enrollment)
   * Does NOT check if user is already enrolled in our system.
   */
  async verifyBiometricOwnership(promptMessage?: string): Promise<boolean> {
      try {
          const compatible = await LocalAuthentication.hasHardwareAsync();
          if (!compatible) throw new Error('Hardware não suportado');

          const enrolled = await LocalAuthentication.isEnrolledAsync();
          if (!enrolled) throw new Error('Nenhuma biometria cadastrada no dispositivo');

          const result = await LocalAuthentication.authenticateAsync({
              promptMessage: promptMessage || 'Confirme sua biometria',
              cancelLabel: 'Cancelar',
              disableDeviceFallback: true, // Force biometrics only for enrollment
          });

          return result.success;
      } catch (error) {
          console.error('[BiometricAuth] Ownership verification failed:', error);
          return false;
      }
  }

  /**
   * Store session token after successful authentication
   */
  async storeSessionToken(userId: string, token: string): Promise<void> {
    try {
      const sessionData = {
        token,
        userId,
        createdAt: new Date().toISOString(),
        expiresAt: new Date(Date.now() + this.SESSION_DURATION_MS).toISOString(),
      };

      await SecureStore.setItemAsync(
        `${this.SESSION_TOKEN_KEY}_${userId}`,
        JSON.stringify(sessionData)
      );

      console.log('[BiometricAuth] Session token stored');
    } catch (error) {
      console.error('[BiometricAuth] Error storing session token:', error);
      throw error;
    }
  }

  /**
   * Validate session token
   */
  async validateSessionToken(userId: string): Promise<boolean> {
    try {
      const sessionDataStr = await SecureStore.getItemAsync(
        `${this.SESSION_TOKEN_KEY}_${userId}`
      );

      if (!sessionDataStr) {
        return false;
      }

      const sessionData = JSON.parse(sessionDataStr);
      const expiresAt = new Date(sessionData.expiresAt);
      const now = new Date();

      // Check if token is expired
      if (now > expiresAt) {
        // Token expired, remove it
        await SecureStore.deleteItemAsync(`${this.SESSION_TOKEN_KEY}_${userId}`);
        return false;
      }

      // Token is valid
      return true;
    } catch (error) {
      console.error('[BiometricAuth] Error validating session token:', error);
      return false;
    }
  }

  /**
   * Get session token
   */
  async getSessionToken(userId: string): Promise<string | null> {
    try {
      const sessionDataStr = await SecureStore.getItemAsync(
        `${this.SESSION_TOKEN_KEY}_${userId}`
      );

      if (!sessionDataStr) {
        return null;
      }

      const sessionData = JSON.parse(sessionDataStr);

      // Validate token before returning
      const isValid = await this.validateSessionToken(userId);
      if (!isValid) {
        return null;
      }

      return sessionData.token;
    } catch (error) {
      console.error('[BiometricAuth] Error getting session token:', error);
      return null;
    }
  }

  /**
   * Clear session token
   */
  async clearSessionToken(userId: string): Promise<void> {
    try {
      await SecureStore.deleteItemAsync(`${this.SESSION_TOKEN_KEY}_${userId}`);
      console.log('[BiometricAuth] Session token cleared');
    } catch (error) {
      console.error('[BiometricAuth] Error clearing session token:', error);
    }
  }

  /**
   * Get enrollment data for user
   */
  private async getEnrollmentData(userId: string): Promise<BiometricEnrollmentData | null> {
    try {
      const dataStr = await SecureStore.getItemAsync(`${this.ENROLLMENT_KEY}_${userId}`);

      if (!dataStr) {
        return null;
      }

      const data = JSON.parse(dataStr);
      return {
        ...data,
        enrolledAt: new Date(data.enrolledAt),
        lastUsedAt: data.lastUsedAt ? new Date(data.lastUsedAt) : null,
      };
    } catch (error) {
      console.error('[BiometricAuth] Error getting enrollment data:', error);
      return null;
    }
  }

  /**
   * Update last used timestamp
   */
  private async updateLastUsed(userId: string): Promise<void> {
    try {
      const enrollmentData = await this.getEnrollmentData(userId);

      if (!enrollmentData) {
        return;
      }

      enrollmentData.lastUsedAt = new Date();

      await SecureStore.setItemAsync(
        `${this.ENROLLMENT_KEY}_${userId}`,
        JSON.stringify(enrollmentData)
      );
    } catch (error) {
      console.error('[BiometricAuth] Error updating last used:', error);
    }
  }

  /**
   * Get security level of biometric authentication
   */
  async getSecurityLevel(): Promise<number> {
    try {
      const securityLevel = await LocalAuthentication.getEnrolledLevelAsync();
      return securityLevel;
    } catch (error) {
      console.error('[BiometricAuth] Error getting security level:', error);
      return 0;
    }
  }

  /**
   * Check if biometric authentication is available and ready
   */
  async isAvailable(): Promise<{
    available: boolean;
    biometricType?: string;
    reason?: string;
  }> {
    try {
      const isSupported = await this.isSupported();
      if (!isSupported) {
        return {
          available: false,
          reason: 'Dispositivo não suporta autenticação biométrica',
        };
      }

      const hasEnrolled = await this.hasEnrolledBiometrics();
      if (!hasEnrolled) {
        return {
          available: false,
          reason: 'Nenhuma biometria cadastrada no dispositivo',
        };
      }

      const types = await this.getAvailableBiometricTypes();
      const biometricName = this.getBiometricTypeName(types);

      return {
        available: true,
        biometricType: biometricName,
      };
    } catch (error) {
      console.error('[BiometricAuth] Error checking availability:', error);
      return {
        available: false,
        reason: 'Erro ao verificar disponibilidade',
      };
    }
  }
  /**
   * Store user credentials securely
   */
  async storeCredentials(userId: string, email: string, password: string): Promise<void> {
    try {
       const creds = { email, password };
       await SecureStore.setItemAsync(`${this.CREDENTIALS_KEY}_${userId}`, JSON.stringify(creds));
    } catch (error) {
       console.error('[BiometricAuth] Error storing credentials:', error);
       throw error;
    }
  }

  /**
   * Get stored credentials
   */
  async getCredentials(userId: string): Promise<{email: string, password: string} | null> {
    try {
      const credsStr = await SecureStore.getItemAsync(`${this.CREDENTIALS_KEY}_${userId}`);
      if (!credsStr) return null;
      return JSON.parse(credsStr);
    } catch (error) {
      console.error('[BiometricAuth] Error getting credentials:', error);
      return null;
    }
  }

  /**
   * Get Last Enrolled User ID
   */
  async getLastEnrolledUser(): Promise<string | null> {
      try {
          return await AsyncStorage.getItem(this.LAST_USER_KEY);
      } catch (e) {
          return null;
      }
  }
}

export default new BiometricAuthService();

/**
 * Cache Layer Service - Intelligent Caching with LRU Eviction
 * 
 * Implements intelligent in-memory caching with:
 * - Configurable TTL (products: 5min, settings: 10min, profiles: 3min)
 * - Cache invalidation when data changes
 * - LRU (Least Recently Used) eviction policy
 * - Memory management (50MB limit)
 * - Tag-based invalidation
 * - Performance metrics tracking
 * 
 * Requirements: 4.1, 4.2, 4.3, 4.4, 4.5, 4.6, 4.7, 11.2
 */

/**
 * Cache entry with LRU tracking
 */
interface CacheEntry<T> {
  key: string;
  data: T;
  timestamp: number;
  ttl: number;
  tags: string[];
  hits: number;
  lastAccessed: number;
  size: number; // Estimated size in bytes
}

/**
 * Cache options for set/withCache operations
 */
interface CacheOptions {
  ttl?: number;
  forceRefresh?: boolean;
  tags?: string[];
}

/**
 * Cache statistics
 */
interface CacheStats {
  hits: number;
  misses: number;
  hitRate: number;
  size: number;
  entries: number;
}

/**
 * TTL defaults for different data types (in milliseconds)
 */
const TTL_DEFAULTS = {
  products: 5 * 60 * 1000,    // 5 minutes
  settings: 10 * 60 * 1000,   // 10 minutes
  profiles: 3 * 60 * 1000,    // 3 minutes
  orders: 30 * 1000,          // 30 seconds
  statistics: 5 * 60 * 1000,  // 5 minutes
  default: 5 * 60 * 1000      // 5 minutes
};

/**
 * Cache Layer Service with LRU Eviction
 */
class CacheLayerService {
  private cache: Map<string, CacheEntry<any>> = new Map();
  private tagIndex: Map<string, Set<string>> = new Map(); // tag -> Set of keys

  private stats = {
    hits: 0,
    misses: 0
  };

  private readonly MAX_MEMORY_BYTES = 50 * 1024 * 1024; // 50MB
  private currentMemoryUsage = 0;
  private compressionThreshold = 10 * 1024; // 10KB default

  /**
   * Configure cache settings
   */
  configure(options: { compressionThreshold?: number }): void {
    if (options.compressionThreshold !== undefined) {
      this.compressionThreshold = options.compressionThreshold;
    }
  }

  /**
   * Get value from cache with expiration checking
   */
  async get<T>(key: string): Promise<T | null> {
    const entry = this.cache.get(key);

    if (!entry) {
      this.stats.misses++;
      return null;
    }

    // Check if expired
    const now = Date.now();
    const age = now - entry.timestamp;

    if (age > entry.ttl) {
      // Cache expired
      this.stats.misses++;
      await this.invalidate(key);
      return null;
    }

    // Cache hit - update LRU tracking
    this.stats.hits++;
    entry.hits++;
    entry.lastAccessed = now;

    return entry.data as T;
  }

  /**
   * Set value in cache with TTL
   */
  async set<T>(key: string, value: T, ttl?: number, tags?: string[]): Promise<void> {
    const now = Date.now();
    const effectiveTTL = ttl || TTL_DEFAULTS.default;

    // Estimate size of the data
    const estimatedSize = this.estimateSize(value);

    // Check if we need to evict entries to make room
    await this.ensureMemoryAvailable(estimatedSize);

    // Remove old entry if exists
    if (this.cache.has(key)) {
      await this.invalidate(key);
    }

    // Create new entry
    const entry: CacheEntry<T> = {
      key,
      data: value,
      timestamp: now,
      ttl: effectiveTTL,
      tags: tags || [],
      hits: 0,
      lastAccessed: now,
      size: estimatedSize
    };

    this.cache.set(key, entry);
    this.currentMemoryUsage += estimatedSize;

    // Update tag index
    if (tags && tags.length > 0) {
      for (const tag of tags) {
        if (!this.tagIndex.has(tag)) {
          this.tagIndex.set(tag, new Set());
        }
        this.tagIndex.get(tag)!.add(key);
      }
    }
  }

  /**
   * Invalidate single cache entry
   */
  async invalidate(key: string): Promise<void> {
    const entry = this.cache.get(key);
    if (!entry) {
      return;
    }

    // Remove from tag index
    for (const tag of entry.tags) {
      const tagSet = this.tagIndex.get(tag);
      if (tagSet) {
        tagSet.delete(key);
        if (tagSet.size === 0) {
          this.tagIndex.delete(tag);
        }
      }
    }

    // Update memory usage
    this.currentMemoryUsage -= entry.size;

    // Remove from cache
    this.cache.delete(key);
  }

  /**
   * Invalidate entries by pattern matching
   */
  async invalidatePattern(pattern: string): Promise<void> {
    const keysToInvalidate: string[] = [];

    for (const key of this.cache.keys()) {
      if (key.includes(pattern)) {
        keysToInvalidate.push(key);
      }
    }

    for (const key of keysToInvalidate) {
      await this.invalidate(key);
    }
  }

  /**
   * Invalidate entries by tag
   */
  async invalidateByTag(tag: string): Promise<void> {
    const tagSet = this.tagIndex.get(tag);
    if (!tagSet) {
      return;
    }

    const keysToInvalidate = Array.from(tagSet);
    for (const key of keysToInvalidate) {
      await this.invalidate(key);
    }
  }

  /**
   * Invalidate multiple tags at once
   */
  async invalidateByTags(tags: string[]): Promise<void> {
    for (const tag of tags) {
      await this.invalidateByTag(tag);
    }
  }

  /**
   * Get cache statistics
   */
  async getStats(): Promise<CacheStats> {
    return {
      hits: this.stats.hits,
      misses: this.stats.misses,
      hitRate: this.getHitRate(),
      size: this.currentMemoryUsage,
      entries: this.cache.size
    };
  }

  /**
   * Calculate hit rate
   */
  getHitRate(): number {
    const total = this.stats.hits + this.stats.misses;
    if (total === 0) {
      return 0;
    }
    return this.stats.hits / total;
  }

  /**
   * Wrapper for operations with automatic caching
   */
  async withCache<T>(
    key: string,
    fetcher: () => Promise<T>,
    options?: CacheOptions
  ): Promise<T> {
    // Check cache first (unless force refresh)
    if (!options?.forceRefresh) {
      const cached = await this.get<T>(key);
      if (cached !== null) {
        return cached;
      }
    }

    // Fetch fresh data
    const data = await fetcher();

    // Store in cache
    await this.set(key, data, options?.ttl, options?.tags);

    return data;
  }

  /**
   * Clear all cache entries
   */
  async clear(): Promise<void> {
    this.cache.clear();
    this.tagIndex.clear();
    this.currentMemoryUsage = 0;
    // Reset stats to ensure clean state
    this.stats = {
      hits: 0,
      misses: 0
    };
  }

  /**
   * Ensure memory is available by evicting LRU entries
   */
  private async ensureMemoryAvailable(requiredBytes: number): Promise<void> {
    // If adding this entry would exceed limit, evict LRU entries
    while (this.currentMemoryUsage + requiredBytes > this.MAX_MEMORY_BYTES && this.cache.size > 0) {
      await this.evictLRU();
    }
  }

  /**
   * Evict least recently used entry
   */
  private async evictLRU(): Promise<void> {
    let lruKey: string | null = null;
    let lruTime = Infinity;

    // Find entry with oldest lastAccessed time
    for (const [key, entry] of this.cache.entries()) {
      if (entry.lastAccessed < lruTime) {
        lruTime = entry.lastAccessed;
        lruKey = key;
      }
    }

    if (lruKey) {
      await this.invalidate(lruKey);
    }
  }

  /**
   * Estimate size of data in bytes
   */
  private estimateSize(data: any): number {
    try {
      const serialized = JSON.stringify(data);
      // Rough estimate: 2 bytes per character in UTF-16
      return serialized.length * 2;
    } catch (error) {
      // If can't serialize, use a default estimate
      return 1024; // 1KB default
    }
  }

  /**
   * Get TTL for a specific data type
   */
  getTTLForType(type: keyof typeof TTL_DEFAULTS): number {
    return TTL_DEFAULTS[type] || TTL_DEFAULTS.default;
  }
}

// Singleton instance
export const cacheLayerService = new CacheLayerService();

// Export for tests
export { CacheLayerService, TTL_DEFAULTS };
export type { CacheEntry, CacheOptions, CacheStats };

/**
 * CaixaService - Gerencia operações de caixa (abertura, reforço, sangria, fechamento, histórico).
 */
import { supabase } from '../config/SupabaseConfig';
import { Caixa } from '../types';
import { Alert } from 'react-native';
import { getLocalDateKey } from '../utils/dateUtils';

const TABLE_CAIXA = 'cash_registers';
const TABLE_MOVIMENTOS = 'cash_movements';

// Cache para caixa aberto (2 minutos)
interface CaixaCache {
  data: Caixa | null;
  timestamp: number;
}

let caixaCache: CaixaCache = { data: null, timestamp: 0 };
const CACHE_TTL = 2 * 60 * 1000;

class CaixaService {

  // Helper: Get user's company ID
  private async _getCompanyId(): Promise<string | null> {
    console.log('[CaixaService] _getCompanyId START');

    // ✅ Add timeout to auth.getUser()
    const getUserPromise = supabase.auth.getUser();
    const timeoutPromise = new Promise<never>((_, reject) => {
      setTimeout(() => reject(new Error('Timeout: auth.getUser() exceeded 3s')), 3000);
    });

    let user;
    try {
      const result = await Promise.race([getUserPromise, timeoutPromise]);
      user = result.data.user;
      console.log('[CaixaService] User fetched:', user?.id);
    } catch (timeoutError: any) {
      console.error('[CaixaService] auth.getUser() timeout:', timeoutError.message);
      throw timeoutError;
    }

    if (!user) {
      console.log('[CaixaService] No user found');
      return null;
    }

    // ✅ Add timeout to profiles query
    console.log('[CaixaService] Querying profiles for company_id...');
    const profileQueryPromise = supabase.from('profiles').select('company_id').eq('id', user.id).single();
    const profileTimeoutPromise = new Promise<never>((_, reject) => {
      setTimeout(() => reject(new Error('Timeout: profiles query exceeded 3s')), 3000);
    });

    try {
      const result = await Promise.race([profileQueryPromise, profileTimeoutPromise]);
      console.log('[CaixaService] Profile company_id:', result.data?.company_id);
      return result.data?.company_id || null;
    } catch (timeoutError: any) {
      console.error('[CaixaService] profiles query timeout:', timeoutError.message);
      throw timeoutError;
    }
  }

  async getCaixaAberto(companyId?: string): Promise<Caixa | null> {
    console.log('[CaixaService] getCaixaAberto START [VERSION 4 - WITH ABORT]', companyId);
    const cid = companyId || await this._getCompanyId();
    console.log('[CaixaService] Company ID resolved:', cid);
    if (!cid) return null;

    const now = Date.now();
    const today = getLocalDateKey();
    console.log('[CaixaService] Today key:', today);

    // Verificar cache: válido se dentro do TTL E do mesmo dia
    if (caixaCache.data && (now - caixaCache.timestamp) < CACHE_TTL) {
      // Validar se o cache é do dia atual
      if (caixaCache.data.data === today) {
        console.log('[CaixaService] Returning from cache');
        return caixaCache.data;
      }
      // Cache é de outro dia, invalidar
      caixaCache = { data: null, timestamp: 0 };
    }

    console.log('[CaixaService] Querying Supabase for caixa aberto... [v4-with-abort]');

    // ✅ Add timeout to prevent hanging
    const queryPromise = supabase
      .from(TABLE_CAIXA)
      .select('*')
      .eq('company_id', cid)
      .eq('status', 'aberto')
      .eq('date_key', today) // ✅ CRÍTICO: Buscar apenas caixa do dia atual
      .limit(1)
      .maybeSingle();

    const timeoutPromise = new Promise<never>((_, reject) => {
      setTimeout(() => {
        console.error('[CaixaService] Timeout reached after 3s');
        reject(new Error('Timeout: getCaixaAberto query exceeded 3s'));
      }, 3000);
    });

    let data, error;
    try {
      console.log('[CaixaService] Starting Promise.race...');
      const result = await Promise.race([queryPromise, timeoutPromise]);
      data = result.data;
      error = result.error;
      console.log('[CaixaService] Promise.race completed successfully');
    } catch (timeoutError: any) {
      console.error('[CaixaService] Query timeout or error:', timeoutError.message);
      // Return null instead of throwing to allow order creation to proceed
      return null;
    }

    console.log('[CaixaService] Query result:', { hasData: !!data, hasError: !!error });

    if (error) {
      console.error('Erro ao buscar caixa aberto:', error.message);
      return null;
    }

    if (data) {
      const mappedCaixa: Caixa = this._mapCaixaToType(data);
      caixaCache = { data: mappedCaixa, timestamp: now };
      console.log('[CaixaService] Caixa found and cached:', mappedCaixa.id);
      return mappedCaixa;
    }

    caixaCache = { data: null, timestamp: now };
    console.log('[CaixaService] No caixa aberto found');
    return null;
  }

  invalidateCache() {
    caixaCache = { data: null, timestamp: 0 };
  }

  async abrirCaixa(companyId: string, valorInicial: string | number, usuarioId: string, usuarioNome: string) {
    if (!companyId) throw new Error("Company ID required");

    const valor = typeof valorInicial === 'string' ? parseFloat(valorInicial) : valorInicial;
    if (isNaN(valor) || valor < 0) throw new Error("Valor inicial inválido.");

    // Check if open exists
    const existente = await this.getCaixaAberto(companyId);
    if (existente) throw new Error('Já existe um caixa aberto para hoje/agora.');

    const { data, error } = await supabase
      .from(TABLE_CAIXA)
      .insert({
        company_id: companyId,
        date_key: getLocalDateKey(),
        opened_by: usuarioId,
        opened_by_name: usuarioNome,
        initial_value: valor,
        expected_balance: valor, // Start with initial
        status: 'aberto',
        sales_by_method: { dinheiro: 0, pix: 0, debito: 0, credito: 0 }
      })
      .select()
      .single();

    if (error) throw new Error(error.message);

    this.invalidateCache();
    return data;
  }

  async registrarReforco(companyId: string, valor: string | number, motivo: string, usuarioId: string, usuarioNome: string) {
    const caixa = await this.getCaixaAberto(companyId);
    if (!caixa) throw new Error('Nenhum caixa aberto.');

    const valorNum = typeof valor === 'string' ? parseFloat(valor) : valor;
    if (!(valorNum > 0)) throw new Error('Valor inválido.');

    // Update Caixa
    // We do optimized increment if possible, or read-modify-write.
    // Supabase doesn't support field increments easily without RPC or raw SQL.
    // Let's use read-modify-write for now, relying on optimistic locking if versioning existed, but here relying on short transaction gap.

    const novoReforcos = (caixa.reforcosTotal || 0) + valorNum;
    const novoSaldo = (caixa.saldoEsperado || 0) + valorNum;

    // Transaction logic: Update Register AND Insert Movement
    // Since Supabase JS client doesn't do multi-table transactions easily, we do them sequentially.
    // Ideally use RPC. For rapid migration, sequential is acceptable if errors handled.

    // 1. Insert Movement
    const { error: movError } = await supabase.from(TABLE_MOVIMENTOS).insert({
      company_id: companyId,
      cash_register_id: caixa.id,
      type: 'reforco',
      value: valorNum,
      reason: motivo,
      user_id: usuarioId,
      user_name: usuarioNome
    });
    if (movError) throw new Error(movError.message);

    // 2. Update Register
    const { error: updError } = await supabase.from(TABLE_CAIXA)
      .update({
        total_reinforcements: novoReforcos,
        expected_balance: novoSaldo,
        updated_at: new Date().toISOString()
      })
      .eq('id', caixa.id);

    if (updError) throw new Error(updError.message);

    this.invalidateCache();
  }

  async registrarSangria(companyId: string, valor: string | number, motivo: string, usuarioId: string, usuarioNome: string) {
    const caixa = await this.getCaixaAberto(companyId);
    if (!caixa) throw new Error('Nenhum caixa aberto.');

    const valorNum = typeof valor === 'string' ? parseFloat(valor) : valor;
    if (!(valorNum > 0)) throw new Error('Valor inválido.');

    if (valorNum > caixa.saldoEsperado) throw new Error('Sangria maior que saldo disponível.');

    const novoSangrias = (caixa.sangriasTotal || 0) + valorNum;
    const novoSaldo = caixa.saldoEsperado - valorNum;

    // 1. Insert Movement
    const { error: movError } = await supabase.from(TABLE_MOVIMENTOS).insert({
      company_id: companyId,
      cash_register_id: caixa.id,
      type: 'sangria',
      value: valorNum,
      reason: motivo,
      user_id: usuarioId,
      user_name: usuarioNome
    });
    if (movError) throw new Error(movError.message);

    // 2. Update Register
    const { error: updError } = await supabase.from(TABLE_CAIXA)
      .update({
        total_bleedings: novoSangrias,
        expected_balance: novoSaldo,
        updated_at: new Date().toISOString()
      })
      .eq('id', caixa.id);

    if (updError) throw new Error(updError.message);

    this.invalidateCache();
  }

  // Used by Order/Payment Service to sync sales
  async registrarVenda(companyId: string, forma: string, valor: number | string) {
    if (!companyId) return;

    const caixa = await this.getCaixaAberto(companyId);
    if (!caixa) throw new Error('Caixa fechado ou inexistente.');

    const valorNum = typeof valor === 'string' ? parseFloat(valor) : valor;
    if (!(valorNum > 0)) return; // Valid?

    const porForma = caixa.porForma || { dinheiro: 0, pix: 0, debito: 0, credito: 0 };
    porForma[forma] = (porForma[forma] || 0) + valorNum; // Update specific method

    const novaVendasTotal = (caixa.vendasTotal || 0) + valorNum;
    const novoSaldo = (caixa.saldoEsperado || 0) + valorNum;
    // Note: SaldoEsperado increases with any sale or just cash? 
    // Usually "Saldo" refers to Cash in Drawer. 
    // If logic is "Saldo Do Caixa" (Money physically there), then only 'dinheiro' increases it.
    // However, original code implies `saldoEsperado = saldoAnterior + valorNum` for ALL sales?
    // Let's re-read original:
    // `const saldoEsperado = saldoAnterior + valorNum;` -> Yes, it added ALL sales to expected balance.
    // That seems odd for a cash register (Pix doesn't go to drawer), but I will replicate original logic 1:1.

    const { error } = await supabase.from(TABLE_CAIXA)
      .update({
        sales_by_method: porForma,
        total_sales: novaVendasTotal,
        expected_balance: novoSaldo,
        updated_at: new Date().toISOString()
      })
      .eq('id', caixa.id);

    if (error) console.error('Erro ao registrar venda no caixa:', error.message);
    else this.invalidateCache();
  }

  async getCaixasAbertos(companyId: string): Promise<Caixa[]> {
    const { data } = await supabase.from(TABLE_CAIXA)
      .select('*')
      .eq('company_id', companyId)
      .eq('status', 'aberto');

    return (data || []).map(this._mapCaixaToType);
  }

  async fecharCaixa(companyId: string, usuarioId: string | null, usuarioNome: string, saldoRealContado: string | number, caixaId?: string) {
    let caixa: Caixa | null = null;

    if (caixaId) {
      const { data } = await supabase.from(TABLE_CAIXA)
        .select('*')
        .eq('id', caixaId)
        .eq('company_id', companyId)
        .single();

      if (data) caixa = this._mapCaixaToType(data);
    } else {
      caixa = await this.getCaixaAberto(companyId);
    }

    if (!caixa) throw new Error('Nenhum caixa aberto encontrado.');

    const saldoReal = typeof saldoRealContado === 'string' ? parseFloat(saldoRealContado) : saldoRealContado;
    const dif = saldoReal - caixa.saldoEsperado;

    const { error } = await supabase.from(TABLE_CAIXA)
      .update({
        status: 'fechado',
        real_balance: saldoReal,
        difference: dif,
        closed_at: new Date().toISOString(),
        closed_by: usuarioId,
        closed_by_name: usuarioNome,
        updated_at: new Date().toISOString()
      })
      .eq('id', caixa.id);

    if (error) throw new Error(error.message);
    this.invalidateCache();

    return {
      saldoEsperado: caixa.saldoEsperado,
      saldoReal,
      diferenca: dif
    };
  }

  async historico(companyId: string, limitVal: number = 30): Promise<Caixa[]> {
    const { data } = await supabase.from(TABLE_CAIXA)
      .select('*')
      .eq('company_id', companyId)
      .order('date_key', { ascending: false })
      .limit(limitVal);

    return (data || []).map(this._mapCaixaToType);
  }

  async getTotalCancelados(companyId: string, dateKey: string): Promise<number> {
    try {
      const { data, error } = await supabase
        .from('comandas')
        .select('total_consumed')
        .eq('company_id', companyId)
        .eq('date_key', dateKey)
        .eq('status', 'cancelada');

      if (error) {
        console.error('Erro ao buscar comandas canceladas:', error.message);
        return 0;
      }

      const total = (data || []).reduce((sum, comanda) => sum + (comanda.total_consumed || 0), 0);
      return total;
    } catch (error) {
      console.error('Erro ao calcular total cancelado:', error);
      return 0;
    }
  }

  // --- Mapper ---
  private _mapCaixaToType(row: any): Caixa {
    return {
      id: row.id,
      data: row.date_key,
      status: row.status,
      abertoPor: row.opened_by,
      abertoPorNome: row.opened_by_name,
      abertoAt: row.opened_at,
      valorInicial: row.initial_value || 0,
      vendasTotal: row.total_sales || 0,
      reforcosTotal: row.total_reinforcements || 0,
      sangriasTotal: row.total_bleedings || 0,
      saldoEsperado: row.expected_balance || 0,
      saldoReal: row.real_balance || 0,
      diferenca: row.difference || 0,
      movimentosCount: row.movements_count || 0,
      fechadoAt: row.closed_at,
      fechadoPor: row.closed_by,
      fechadoPorNome: row.closed_by_name,
      porForma: row.sales_by_method || { dinheiro: 0, pix: 0, debito: 0, credito: 0 }
    };
  }
}

export default new CaixaService();

import { supabase } from '../config/SupabaseConfig';
// @ts-ignore
import { convertUnit } from '../utils/unitConversion';
import OfflineQueueService from './OfflineQueueService';
import { Ingredient } from '../types';

interface OrderItem {
  name?: string;
  nome?: string;
  quantidade?: number;
  inventoryItems?: Ingredient[];
  [key: string]: any;
}

class InventoryService {
    /**
     * Realiza a baixa de estoque para uma lista de itens do pedido.
     * @param {string} companyId - ID da empresa
     * @param {Array} orderItems - Itens do pedido (devem conter inventoryItems se configurado)
     */
    async deductStock(companyId: string, orderItems: any[]): Promise<{ totalCost: number; error?: any }> {
        try {
            const result = await this.processStockDeduction(companyId, orderItems, false);
            return result;
        } catch (error) {
            console.error('[InventoryService] Erro inicial ao baixar estoque. Adicionando à fila.', error);
            return { totalCost: 0, error };
        }
    }

    /**
     * Lógica interna de processamento.
     * @param {string} companyId 
     * @param {Array} orderItems 
     * @param {boolean} isRetry - Indica se é uma re-tentativa da fila (para não loopear)
     * @returns {Promise<{totalCost: number}>}
     */
    async processStockDeduction(companyId: string, orderItems: any[], isRetry: boolean = false): Promise<{ totalCost: number }> {
        if (!companyId || !orderItems || orderItems.length === 0) return { totalCost: 0 };

        try {
            const stockIdsToFetch = new Set<string>();
            const deductions: { stockId: string; reqQty: number; reqUnit: string }[] = [];
            let hasInventoryItems = false;

            // Extract quantity from item (e.g., "2x Coca")
            for (const item of orderItems) {
                const itemNome = item.nome || item.name || '';
                const qtyMatch = typeof item === 'string'
                    ? item.match(/^(\d+)x/)
                    : (itemNome).match(/^(\d+)x/);

                const orderQty = qtyMatch ? parseInt(qtyMatch[1], 10) : (item.quantidade || 1);

                if (item.inventoryItems && Array.isArray(item.inventoryItems)) {
                    hasInventoryItems = true;
                    item.inventoryItems.forEach((ingrediente: Ingredient) => {
                        if (ingrediente.id) {
                            stockIdsToFetch.add(ingrediente.id);
                            deductions.push({
                                stockId: ingrediente.id,
                                reqQty: (ingrediente.qt || 0) * orderQty,
                                reqUnit: ingrediente.un
                            });
                        }
                    });
                }
            }

            if (!hasInventoryItems) {
                return { totalCost: 0 };
            }

            if (stockIdsToFetch.size === 0) return { totalCost: 0 };

            // Fetch current stock data
            const stockIds = Array.from(stockIdsToFetch);
            const { data: stockItems, error: fetchError } = await supabase
                .from('inventory')
                .select('*')
                .eq('company_id', companyId)
                .in('id', stockIds);

            if (fetchError) {
                throw fetchError;
            }

            const stockMap: Record<string, any> = {};
            (stockItems || []).forEach(item => {
                stockMap[item.id] = item;
            });

            // Process deductions
            let totalCost = 0;
            const updates: any[] = [];

            for (const ded of deductions) {
                const stockItem = stockMap[ded.stockId];
                if (!stockItem) {
                    console.warn(`[InventoryService] Item de estoque ${ded.stockId} não encontrado/excluído.`);
                    continue;
                }

                // Unit conversion
                const convertedAmount = convertUnit(ded.reqQty, ded.reqUnit, stockItem.unidade);

                if (convertedAmount !== null && convertedAmount > 0) {
                    const newQuantity = (stockItem.quantidade || 0) - convertedAmount;

                    // Update stock quantity
                    updates.push(
                        supabase
                            .from('inventory')
                            .update({
                                quantidade: newQuantity,
                                atualizado_em: new Date().toISOString()
                            })
                            .eq('company_id', companyId)
                            .eq('id', ded.stockId)
                    );

                    // Calculate cost (CMV)
                    if (stockItem.preco_custo) {
                        const custoParcela = Number(stockItem.preco_custo) * convertedAmount;
                        totalCost += custoParcela;
                    }
                } else {
                    console.warn(`[InventoryService] Falha na conversão ou valor zero: ${ded.reqQty} ${ded.reqUnit} -> ${stockItem.unidade}`);
                }
            }

            if (updates.length > 0) {
                await Promise.all(updates);
                console.log(`[InventoryService] Baixa efetuada em ${updates.length} itens. Custo Total (CMV): R$ ${totalCost.toFixed(2)}`);
            }

            return { totalCost };

        } catch (error) {
            console.error('[InventoryService] Erro no processStockDeduction:', error);

            if (!isRetry) {
                await OfflineQueueService.enqueue('STOCK_DEDUCTION', async () => ({ totalCost: 0 }), {
                    companyId,
                    orderItems: orderItems
                });
            } else {
                throw error;
            }
            return { totalCost: 0 };
        }
    }
}

export default new InventoryService();

/**
 * LoggerService.ts
 * Service for centralized logging and error reporting with Sentry
 * 
 * Requirements: 22.1, 22.2
 */

import * as Sentry from '@sentry/react-native';

// ============================================================================
// TYPES
// ============================================================================

type LogLevel = 'info' | 'warning' | 'error' | 'debug' | 'fatal';

interface LogContext {
  [key: string]: any;
}

interface SentryTags {
  context?: string;
  [key: string]: string | undefined;
}

interface SentryExtra {
  [key: string]: any;
}

// ============================================================================
// LOGGER SERVICE CLASS
// ============================================================================

/**
 * Service for centralized logging and error reporting.
 */
class LoggerService {
  /**
   * Log an error to Sentry and Console
   */
  logError(error: Error | string, context: string = '', extra: SentryExtra = {}): void {
    if (__DEV__) {
      console.error(`[${context}]`, error, extra);
    }

    const errorObj = typeof error === 'string' ? new Error(error) : error;
    const scrubbedExtra = this.scrubData(extra);

    Sentry.captureException(errorObj, {
      tags: { context } as SentryTags,
      extra: scrubbedExtra,
    });
  }

  /**
   * Scrub sensitive data from logs
   */
  private scrubData(data: any): any {
    if (!data) return data;

    // Deep copy to avoid mutating original data
    try {
      const sensitiveKeys = ['password', 'token', 'secret', 'auth', 'key', 'credit_card', 'cvv', 'card_number'];
      const str = JSON.stringify(data);
      const parsed = JSON.parse(str);

      const redact = (obj: any) => {
        if (typeof obj !== 'object' || obj === null) return;

        Object.keys(obj).forEach(key => {
          const lowerKey = key.toLowerCase();
          if (sensitiveKeys.some(k => lowerKey.includes(k))) {
            obj[key] = '[REDACTED]';
          } else if (typeof obj[key] === 'object') {
            redact(obj[key]);
          }
        });
      };

      redact(parsed);
      return parsed;

    } catch (e) {
      return data; // Return original if parsing fails
    }
  }

  /**
   * Log a message (breadcrumbs in Sentry)
   */
  log(message: string, level: LogLevel = 'info'): void {
    if (__DEV__) {
      console.log(`[${level.toUpperCase()}] ${message}`);
    }

    Sentry.addBreadcrumb({
      message,
      level: level as Sentry.SeverityLevel,
    });
  }

  /**
   * Log info message
   */
  info(message: string, context?: LogContext): void {
    this.log(message, 'info');
    if (context && __DEV__) {
      console.log('[INFO]', context);
    }
  }

  /**
   * Log warning message
   */
  warn(message: string, context?: LogContext): void {
    this.log(message, 'warning');
    if (context && __DEV__) {
      console.warn('[WARN]', context);
    }
  }

  /**
   * Log debug message (only in development)
   */
  debug(message: string, context?: LogContext): void {
    if (__DEV__) {
      console.log('[DEBUG]', message, context);
    }
  }

  /**
   * Set user context for Sentry
   */
  setUser(userId: string, email?: string, username?: string): void {
    Sentry.setUser({
      id: userId,
      email,
      username,
    });
  }

  /**
   * Clear user context
   */
  clearUser(): void {
    Sentry.setUser(null);
  }

  /**
   * Add custom context to Sentry
   */
  setContext(key: string, context: LogContext): void {
    Sentry.setContext(key, context);
  }

  /**
   * Add tag to Sentry
   */
  setTag(key: string, value: string): void {
    Sentry.setTag(key, value);
  }
}

