/**
 * Query Optimizer Service
 * 
 * Otimiza queries ao Firestore com:
 * - Filtros por status para active orders
 * - Limit de 100 resultados
 * - Uso de índices compostos
 * - Handling para lista vazia sem query
 * 
 * Requirements: 9.1, 9.2, 9.3, 9.4, 9.5
 */

import {
  collection,
  query,
  where,
  orderBy,
  limit,
  getDocs,
  QueryConstraint,
  CollectionReference
} from 'firebase/firestore';
import { db } from '../config/firebaseConfig';
import { cacheLayerService } from './CacheLayerService';

/**
 * Configuração do optimizer
 */
interface OptimizerConfig {
  maxResults: number;
  cacheActiveOrdersTTL: number;
  cacheStatsTTL: number;
  enableCache: boolean;
}

/**
 * Resultado de query paginada
 */
interface PageResult<T> {
  items: T[];
  nextCursor?: string;
  hasMore: boolean;
}

/**
 * Query Optimizer Service
 */
class QueryOptimizerService {
  private config: OptimizerConfig = {
    maxResults: 100,
    cacheActiveOrdersTTL: 30 * 1000, // 30 segundos
    cacheStatsTTL: 5 * 60 * 1000, // 5 minutos
    enableCache: true
  };

  /**
   * Obtém pedidos ativos otimizado
   */
  async getActiveOrders(
    companyId: string,
    options?: { limit?: number; useCache?: boolean }
  ): Promise<any[]> {
    const cacheKey = `active-orders:${companyId}`;
    const useCache = options?.useCache !== false && this.config.enableCache;

    // Tenta cache primeiro
    if (useCache) {
      const cached = await cacheLayerService.get<any[]>(cacheKey);
      if (cached !== null) {
        return cached;
      }
    }

    // Query otimizada com índice composto
    const ordersRef = collection(db, `companies/${companyId}/orders`);

    // Filtro por status: apenas pending e preparing
    const constraints: QueryConstraint[] = [
      where('status', 'in', ['pending', 'preparing']),
      orderBy('createdAt', 'desc'),
      limit(options?.limit || this.config.maxResults)
    ];

    const q = query(ordersRef, ...constraints);
    const snapshot = await getDocs(q);

    // Converte para array
    const orders = snapshot.docs.map(doc => ({
      id: doc.id,
      ...doc.data()
    }));

    // Cacheia resultado
    if (useCache) {
      await cacheLayerService.set(
        cacheKey,
        orders,
        this.config.cacheActiveOrdersTTL
      );
    }

    return orders;
  }

  /**
   * Obtém pedidos por comanda (query única otimizada)
   */
  async getOrdersByComanda(
    companyId: string,
    comandaNumber: string
  ): Promise<any[]> {
    // Normaliza comandaNumber
    const normalizedComanda = this.normalizeComandaNumber(comandaNumber);

    const cacheKey = `orders-comanda:${companyId}:${normalizedComanda}`;

    // Tenta cache
    if (this.config.enableCache) {
      const cached = await cacheLayerService.get<any[]>(cacheKey);
      if (cached !== null) {
        return cached;
      }
    }

    // Query única usando índice em comandaNumber
    const ordersRef = collection(db, `companies/${companyId}/orders`);
    const q = query(
      ordersRef,
      where('comandaNumber', '==', normalizedComanda),
      orderBy('createdAt', 'desc')
    );

    try {
      const snapshot = await getDocs(q);
      const orders = snapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      }));

      // Cacheia resultado
      if (this.config.enableCache) {
        await cacheLayerService.set(cacheKey, orders, this.config.cacheActiveOrdersTTL);
      }

      return orders;
    } catch (error) {
      console.error('[QueryOptimizer] Error querying by comanda:', error);
      // Retorna lista vazia em caso de erro
      return [];
    }
  }

  /**
   * Obtém pedidos por range de datas
   */
  async getOrdersByDateRange(
    companyId: string,
    startDate: string,
    endDate: string
  ): Promise<any[]> {
    const cacheKey = `orders-range:${companyId}:${startDate}:${endDate}`;

    // Tenta cache
    if (this.config.enableCache) {
      const cached = await cacheLayerService.get<any[]>(cacheKey);
      if (cached !== null) {
        return cached;
      }
    }

    const ordersRef = collection(db, `companies/${companyId}/orders`);
    const q = query(
      ordersRef,
      where('dateKey', '>=', startDate),
      where('dateKey', '<=', endDate),
      orderBy('dateKey', 'desc'),
      orderBy('createdAt', 'desc'),
      limit(this.config.maxResults)
    );

    const snapshot = await getDocs(q);
    const orders = snapshot.docs.map(doc => ({
      id: doc.id,
      ...doc.data()
    }));

    // Cacheia resultado
    if (this.config.enableCache) {
      await cacheLayerService.set(cacheKey, orders, this.config.cacheStatsTTL);
    }

    return orders;
  }

  /**
   * Obtém pedidos pagos por data
   */
  async getPaidOrdersByDate(
    companyId: string,
    dateKey: string
  ): Promise<any[]> {
    const cacheKey = `paid-orders:${companyId}:${dateKey}`;

    // Tenta cache
    if (this.config.enableCache) {
      const cached = await cacheLayerService.get<any[]>(cacheKey);
      if (cached !== null) {
        return cached;
      }
    }

    const ordersRef = collection(db, `companies/${companyId}/orders`);
    const q = query(
      ordersRef,
      where('isPago', '==', true),
      where('dateKey', '==', dateKey),
      orderBy('createdAt', 'desc')
    );

    const snapshot = await getDocs(q);
    const orders = snapshot.docs.map(doc => ({
      id: doc.id,
      ...doc.data()
    }));

    // Cacheia resultado
    if (this.config.enableCache) {
      await cacheLayerService.set(cacheKey, orders, this.config.cacheStatsTTL);
    }

    return orders;
  }

  /**
   * Normaliza número de comanda para formato consistente
   */
  normalizeComandaNumber(comandaNumber: string | number): string {
    // Remove espaços e converte para string
    const str = String(comandaNumber).trim();

    // Remove zeros à esquerda mas mantém pelo menos 1 dígito
    const normalized = str.replace(/^0+/, '') || '0';

    return normalized;
  }

  /**
   * Invalida cache relacionado a pedidos
   */
  async invalidateOrdersCache(companyId: string): Promise<void> {
    await cacheLayerService.invalidatePattern(`orders:${companyId}`);
    await cacheLayerService.invalidatePattern(`active-orders:${companyId}`);
    await cacheLayerService.invalidatePattern(`paid-orders:${companyId}`);
  }

  /**
   * Invalida cache de uma comanda específica
   */
  async invalidateComandaCache(companyId: string, comandaNumber: string): Promise<void> {
    const normalized = this.normalizeComandaNumber(comandaNumber);
    await cacheLayerService.invalidate(`orders-comanda:${companyId}:${normalized}`);
  }

  /**
   * Obtém estatísticas de cache
   */
  async getCacheStats() {
    return await cacheLayerService.getStats();
  }

  /**
   * Configura parâmetros do optimizer
   */
  configure(config: Partial<OptimizerConfig>): void {
    this.config = { ...this.config, ...config };
  }
}

// Singleton instance
export const queryOptimizerService = new QueryOptimizerService();

// Export para testes
export { QueryOptimizerService };
export type { OptimizerConfig, PageResult };

/**
 * Rate Limiter Service - Migrado para Supabase
 * 
 * Implementa proteção contra ataques de negação de serviço através de:
 * - Limites de operações por minuto (100 writes, 500 reads)
 * - Exponential backoff para violações repetidas
 * - Tracking de padrões suspeitos
 * 
 * Requirements: 4.1, 4.2, 4.3, 4.4, 4.5
 */

import { supabase } from '../config/SupabaseConfig';

// Tipos de operação
export type OperationType = 'read' | 'write';

// Limites por tipo de operação (por minuto)
const RATE_LIMITS: Record<OperationType, number> = {
  read: 500,
  write: 100
};

// Configuração de exponential backoff
const BACKOFF_CONFIG = {
  baseDelayMs: 1000,        // 1 segundo inicial
  maxDelayMs: 300000,       // 5 minutos máximo
  violationThreshold: 3     // Número de violações para bloquear
};

/**
 * Erro lançado quando rate limit é excedido
 */
export class RateLimitError extends Error {
  constructor(
    message: string,
    public retryAfter: number,
    public operationType: OperationType,
    public currentCount: number,
    public limit: number
  ) {
    super(message);
    this.name = 'RateLimitError';
  }
}

/**
 * Informações de rate limit para um usuário
 */
interface RateLimitInfo {
  userId: string;
  reads: number;
  writes: number;
  windowStart: string;
  violations: number;
  blockedUntil?: string;
  lastViolation?: string;
}

/**
 * Serviço de Rate Limiting
 */
export class RateLimiterService {
  private readonly tableName = 'rate_limits';

  /**
   * Verifica se operação está dentro do rate limit
   * @throws {RateLimitError} Se limite for excedido
   */
  async checkLimit(userId: string, operationType: OperationType): Promise<void> {
    const limitInfo = await this.getLimitInfo(userId);

    // Verifica se usuário está bloqueado
    if (limitInfo.blockedUntil) {
      const now = new Date();
      const blockedUntil = new Date(limitInfo.blockedUntil);

      if (blockedUntil.getTime() > now.getTime()) {
        const retryAfter = Math.ceil((blockedUntil.getTime() - now.getTime()) / 1000);
        throw new RateLimitError(
          `Usuário temporariamente bloqueado devido a violações repetidas. Tente novamente em ${retryAfter} segundos.`,
          retryAfter,
          operationType,
          0,
          0
        );
      } else {
        // Bloqueio expirou, limpa o bloqueio
        await this.clearBlock(userId);
      }
    }

    // Verifica se janela de tempo expirou (1 minuto)
    const now = new Date();
    const windowStart = new Date(limitInfo.windowStart);
    const windowDurationMs = 60 * 1000; // 1 minuto
    const windowExpired = (now.getTime() - windowStart.getTime()) > windowDurationMs;

    if (windowExpired) {
      // Reset contadores para nova janela
      await this.resetWindow(userId);
      return; // Primeira operação da nova janela sempre passa
    }

    // Verifica limite específico da operação
    const currentCount = operationType === 'read' ? limitInfo.reads : limitInfo.writes;
    const limit = RATE_LIMITS[operationType];

    if (currentCount >= limit) {
      // Limite excedido - registra violação
      await this.recordViolation(userId, operationType);

      // Calcula retry-after baseado em violações
      const retryAfter = this.calculateRetryAfter(limitInfo.violations + 1);

      throw new RateLimitError(
        `Limite de ${operationType === 'read' ? 'leituras' : 'escritas'} excedido. Máximo: ${limit} operações por minuto.`,
        retryAfter,
        operationType,
        currentCount,
        limit
      );
    }

    // Incrementa contador
    await this.incrementCounter(userId, operationType);
  }

  /**
   * Obtém informações de rate limit para um usuário
   */
  private async getLimitInfo(userId: string): Promise<RateLimitInfo> {
    const { data, error } = await supabase
      .from(this.tableName)
      .select('*')
      .eq('user_id', userId)
      .single();

    if (error || !data) {
      // Primeira vez - cria documento
      const initialInfo = {
        user_id: userId,
        reads_count: 0,
        writes_count: 0,
        window_start: new Date().toISOString(),
        violations: 0
      };

      const { data: newData, error: insertError } = await supabase
        .from(this.tableName)
        .insert(initialInfo)
        .select()
        .single();

      if (insertError) {
        console.error('[RateLimiter] Erro ao criar registro:', insertError);
        throw insertError;
      }

      return {
        userId,
        reads: 0,
        writes: 0,
        windowStart: initialInfo.window_start,
        violations: 0
      };
    }

    return {
      userId: data.user_id,
      reads: data.reads_count || 0,
      writes: data.writes_count || 0,
      windowStart: data.window_start,
      violations: data.violations || 0,
      blockedUntil: data.blocked_until,
      lastViolation: data.last_violation
    };
  }

  /**
   * Incrementa contador de operações
   */
  private async incrementCounter(userId: string, operationType: OperationType): Promise<void> {
    const field = operationType === 'read' ? 'reads_count' : 'writes_count';

    // Usa RPC para incremento atômico
    const { error } = await supabase.rpc('increment_rate_limit', {
      p_user_id: userId,
      p_field: field
    });

    if (error) {
      // Fallback: update manual
      const limitInfo = await this.getLimitInfo(userId);
      const newCount = (operationType === 'read' ? limitInfo.reads : limitInfo.writes) + 1;

      await supabase
        .from(this.tableName)
        .update({ [field]: newCount })
        .eq('user_id', userId);
    }
  }

  /**
   * Reseta janela de tempo
   */
  private async resetWindow(userId: string): Promise<void> {
    const { error } = await supabase
      .from(this.tableName)
      .update({
        reads_count: 0,
        writes_count: 0,
        window_start: new Date().toISOString()
      })
      .eq('user_id', userId);

    if (error) {
      console.error('[RateLimiter] Erro ao resetar janela:', error);
    }
  }

  /**
   * Registra violação de rate limit
   */
  private async recordViolation(userId: string, operationType: OperationType): Promise<void> {
    const limitInfo = await this.getLimitInfo(userId);

    const newViolations = limitInfo.violations + 1;
    const updates: any = {
      violations: newViolations,
      last_violation: new Date().toISOString()
    };

    // Se atingiu threshold, bloqueia usuário
    if (newViolations >= BACKOFF_CONFIG.violationThreshold) {
      const blockDurationMs = this.calculateBlockDuration(newViolations);
      const blockedUntil = new Date(Date.now() + blockDurationMs);

      updates.blocked_until = blockedUntil.toISOString();

      // Log para monitoramento
      console.warn(`[RateLimiter] Usuário ${userId} bloqueado por ${blockDurationMs}ms após ${newViolations} violações`);

      // Alertar administradores sobre padrão suspeito
      if (newViolations >= 5) {
        this.alertAdministrators(userId, newViolations, operationType);
      }
    }

    const { error } = await supabase
      .from(this.tableName)
      .update(updates)
      .eq('user_id', userId);

    if (error) {
      console.error('[RateLimiter] Erro ao registrar violação:', error);
    }
  }

  /**
   * Calcula duração do bloqueio com exponential backoff
   */
  private calculateBlockDuration(violations: number): number {
    const exponent = violations - BACKOFF_CONFIG.violationThreshold + 1;
    const duration = BACKOFF_CONFIG.baseDelayMs * Math.pow(2, exponent);

    return Math.min(duration, BACKOFF_CONFIG.maxDelayMs);
  }

  /**
   * Calcula retry-after em segundos
   */
  private calculateRetryAfter(violations: number): number {
    if (violations < BACKOFF_CONFIG.violationThreshold) {
      return 60; // 1 minuto padrão
    }

    const blockDurationMs = this.calculateBlockDuration(violations);
    return Math.ceil(blockDurationMs / 1000);
  }

  /**
   * Limpa bloqueio expirado
   */
  private async clearBlock(userId: string): Promise<void> {
    const { error } = await supabase
      .from(this.tableName)
      .update({
        blocked_until: null,
        violations: 0
      })
      .eq('user_id', userId);

    if (error) {
      console.error('[RateLimiter] Erro ao limpar bloqueio:', error);
    }
  }

  /**
   * Alerta administradores sobre padrão suspeito
   */
  private async alertAdministrators(
    userId: string,
    violations: number,
    operationType: OperationType
  ): Promise<void> {
    // TODO: Implementar notificação para administradores
    // Pode ser via Edge Function, email, Slack, etc.
    console.error(`[RateLimiter] ALERTA: Usuário ${userId} com ${violations} violações de ${operationType}`);

    // Por enquanto, apenas log
    // Em produção, integrar com sistema de alertas
  }

  /**
   * Obtém estatísticas de rate limiting (para debugging/monitoring)
   */
  async getStats(userId: string): Promise<RateLimitInfo | null> {
    const { data, error } = await supabase
      .from(this.tableName)
      .select('*')
      .eq('user_id', userId)
      .single();

    if (error || !data) {
      return null;
    }

    return {
      userId: data.user_id,
      reads: data.reads_count || 0,
      writes: data.writes_count || 0,
      windowStart: data.window_start,
      violations: data.violations || 0,
      blockedUntil: data.blocked_until,
      lastViolation: data.last_violation
    };
  }

  /**
   * Reseta violações de um usuário (admin only)
   */
  async resetViolations(userId: string): Promise<void> {
    const { error } = await supabase
      .from(this.tableName)
      .update({
        violations: 0,
        blocked_until: null,
        last_violation: null
      })
      .eq('user_id', userId);

    if (error) {
      console.error('[RateLimiter] Erro ao resetar violações:', error);
    }
  }
}

// Singleton instance
export const rateLimiterService = new RateLimiterService();

/**
 * Retry Service - Retry Logic with Idempotency
 * 
 * Implementa retry logic com:
 * - Exponential backoff (1s, 2s, 4s)
 * - Classificação de erros (retryable vs non-retryable)
 * - Logging de falhas após max retries
 * - Idempotency keys para prevenir duplicação
 * - Integração com offline queue
 * 
 * Requirements: 16.1, 16.2, 16.3, 16.4, 16.5
 */

import {
  AppError,
  isRetryableError,
  classifyError,
  NetworkError,
  TimeoutError,
  DatabaseError
} from '../utils/errors';

/**
 * Configuração de retry
 */
interface RetryConfig {
  maxRetries: number;
  initialBackoffMs: number;
  maxBackoffMs: number;
  backoffMultiplier: number;
  enableLogging: boolean;
}

/**
 * Opções de retry para operação
 */
interface RetryOptions {
  maxRetries?: number;
  idempotencyKey?: string;
  context?: Record<string, any>;
  onRetry?: (attempt: number, error: Error) => void;
}

/**
 * Resultado de operação com retry
 */
interface RetryResult<T> {
  success: boolean;
  data?: T;
  error?: Error;
  attempts: number;
  totalDuration: number;
}

/**
 * Registro de operação idempotente
 */
interface IdempotentOperation {
  key: string;
  result: any;
  timestamp: number;
  expiresAt: number;
}

/**
 * Retry Service
 */
class RetryService {
  private config: RetryConfig = {
    maxRetries: 3,
    initialBackoffMs: 1000, // 1 segundo
    maxBackoffMs: 16000, // 16 segundos
    backoffMultiplier: 2,
    enableLogging: true
  };

  // Cache de operações idempotentes (em memória)
  private idempotentCache: Map<string, IdempotentOperation> = new Map();
  private readonly IDEMPOTENCY_TTL = 24 * 60 * 60 * 1000; // 24 horas

  /**
   * Executa operação com retry e exponential backoff
   */
  async withRetry<T>(
    operation: () => Promise<T>,
    options?: RetryOptions
  ): Promise<T> {
    const maxRetries = options?.maxRetries ?? this.config.maxRetries;
    const idempotencyKey = options?.idempotencyKey;
    const startTime = Date.now();

    // Verifica idempotency cache
    if (idempotencyKey) {
      const cached = this.getIdempotentResult<T>(idempotencyKey);
      if (cached !== null) {
        if (this.config.enableLogging) {
          console.log('[RetryService] Returning cached idempotent result', {
            idempotencyKey
          });
        }
        return cached;
      }
    }

    let lastError: Error | null = null;
    let attempt = 0;

    while (attempt <= maxRetries) {
      try {
        const result = await operation();

        // Armazena resultado idempotente
        if (idempotencyKey) {
          this.storeIdempotentResult(idempotencyKey, result);
        }

        // Log sucesso após retry
        if (attempt > 0 && this.config.enableLogging) {
          console.log('[RetryService] Operation succeeded after retries', {
            attempt,
            duration: Date.now() - startTime,
            idempotencyKey,
            context: options?.context
          });
        }

        return result;
      } catch (error) {
        lastError = error as Error;
        const appError = classifyError(error);

        // Não retry se erro não é retryable
        if (!this.isRetryable(appError)) {
          if (this.config.enableLogging) {
            console.error('[RetryService] Non-retryable error, aborting', {
              error: appError.toJSON(),
              attempt,
              context: options?.context
            });
          }
          throw appError;
        }

        // Não retry se atingiu máximo
        if (attempt === maxRetries) {
          break;
        }

        // Calcula delay com exponential backoff
        const delay = this.calculateBackoff(attempt);

        if (this.config.enableLogging) {
          console.warn('[RetryService] Retrying after error', {
            error: appError.message,
            attempt: attempt + 1,
            maxRetries,
            delayMs: delay,
            context: options?.context
          });
        }

        // Callback de retry
        if (options?.onRetry) {
          options.onRetry(attempt + 1, appError);
        }

        // Aguarda antes de retry
        await this.sleep(delay);

        attempt++;
      }
    }

    // Log falha após todos os retries
    const duration = Date.now() - startTime;
    if (this.config.enableLogging) {
      console.error('[RetryService] Operation failed after max retries', {
        error: lastError?.message,
        stack: lastError?.stack,
        attempts: attempt + 1,
        maxRetries,
        duration,
        idempotencyKey,
        context: options?.context
      });
    }

    throw lastError || new Error('Operation failed after max retries');
  }

  /**
   * Verifica se erro é retryable
   */
  private isRetryable(error: Error): boolean {
    // Usa função de classificação do sistema de erros
    if (isRetryableError(error)) {
      return true;
    }

    // Verifica tipos específicos de erro
    if (
      error instanceof NetworkError ||
      error instanceof TimeoutError ||
      (error instanceof DatabaseError && error.retryable)
    ) {
      return true;
    }

    // Verifica mensagens de erro conhecidas
    const message = error.message.toLowerCase();
    const retryablePatterns = [
      'network',
      'timeout',
      'econnrefused',
      'enotfound',
      'etimedout',
      'unavailable',
      'deadline-exceeded',
      'resource-exhausted',
      'aborted',
      'internal'
    ];

    return retryablePatterns.some(pattern => message.includes(pattern));
  }

  /**
   * Calcula delay com exponential backoff
   */
  private calculateBackoff(attempt: number): number {
    const exponentialDelay =
      this.config.initialBackoffMs * Math.pow(this.config.backoffMultiplier, attempt);

    // Adiciona jitter (±25%) para evitar thundering herd
    const jitter = exponentialDelay * 0.25 * (Math.random() * 2 - 1);
    const delayWithJitter = exponentialDelay + jitter;

    // Limita ao máximo configurado
    return Math.min(delayWithJitter, this.config.maxBackoffMs);
  }

  /**
   * Sleep helper
   */
  private sleep(ms: number): Promise<void> {
    return new Promise(resolve => setTimeout(resolve, ms));
  }

  /**
   * Armazena resultado de operação idempotente
   */
  private storeIdempotentResult<T>(key: string, result: T): void {
    const now = Date.now();
    const operation: IdempotentOperation = {
      key,
      result,
      timestamp: now,
      expiresAt: now + this.IDEMPOTENCY_TTL
    };

    this.idempotentCache.set(key, operation);

    // Limpa cache expirado periodicamente
    this.cleanupExpiredCache();
  }

  /**
   * Obtém resultado de operação idempotente
   */
  private getIdempotentResult<T>(key: string): T | null {
    const operation = this.idempotentCache.get(key);

    if (!operation) {
      return null;
    }

    // Verifica se expirou
    if (Date.now() > operation.expiresAt) {
      this.idempotentCache.delete(key);
      return null;
    }

    return operation.result as T;
  }

  /**
   * Limpa entradas expiradas do cache
   */
  private cleanupExpiredCache(): void {
    const now = Date.now();
    const keysToDelete: string[] = [];

    this.idempotentCache.forEach((operation, key) => {
      if (now > operation.expiresAt) {
        keysToDelete.push(key);
      }
    });

    keysToDelete.forEach(key => this.idempotentCache.delete(key));
  }

  /**
   * Gera idempotency key única
   */
  generateIdempotencyKey(operation: string, params: Record<string, any>): string {
    const paramsStr = JSON.stringify(params, Object.keys(params).sort());
    const timestamp = Date.now();
    return `${operation}:${paramsStr}:${timestamp}`;
  }

  /**
   * Limpa cache de idempotência
   */
  clearIdempotencyCache(): void {
    this.idempotentCache.clear();
  }

  /**
   * Obtém estatísticas do cache de idempotência
   */
  getIdempotencyCacheStats() {
    const now = Date.now();
    let activeCount = 0;
    let expiredCount = 0;

    this.idempotentCache.forEach(operation => {
      if (now > operation.expiresAt) {
        expiredCount++;
      } else {
        activeCount++;
      }
    });

    return {
      total: this.idempotentCache.size,
      active: activeCount,
      expired: expiredCount
    };
  }

  /**
   * Configura parâmetros do retry service
   */
  configure(config: Partial<RetryConfig>): void {
    this.config = { ...this.config, ...config };
  }
}

// Singleton instance
export const retryService = new RetryService();

// Export para testes
export { RetryService };
export type { RetryConfig, RetryOptions, RetryResult, IdempotentOperation };

/**
 * SuccessMetricsService - Track modernization success metrics
 * Measures P95 latency, costs, security, and code quality
 */

import {
  collection,
  doc,
  setDoc,
  getDoc,
  getDocs,
  query,
  where,
  orderBy,
  limit as firestoreLimit,
  Timestamp,
  Firestore,
} from 'firebase/firestore';
// @ts-ignore - firebaseConfig.js is not typed
// import { db as dbImport } from '../config/firebaseConfig'; // Removed - Firebase specific
import PerformanceMonitoringService from './PerformanceMonitoringService';

// Type the db import
// @ts-ignore
// const db = dbImport as Firestore; // Removed - Firebase specific
const db: any = null; // Temporarily disabled

export interface BaselineMetrics {
  timestamp: number;
  p95Latency: {
    fetchOrders: number;
    createOrder: number;
    updateOrder: number;
    deleteOrder: number;
    getDailySummary: number;
  };
  firestoreCosts: {
    reads: number;
    writes: number;
    deletes: number;
    estimatedMonthlyCost: number;
  };
  securityIncidents: {
    authFailures: number;
    permissionDenied: number;
    rateLimitViolations: number;
    suspiciousActivity: number;
  };
  codeQuality: {
    testCoverage: number;
    typeScriptAdoption: number;
    lintErrors: number;
    codeSmells: number;
  };
}

export interface CurrentMetrics extends BaselineMetrics {
  improvements: {
    p95LatencyReduction: number; // percentage
    costReduction: number; // percentage
    securityIncidentsReduction: number; // percentage
    codeQualityImprovement: number; // percentage
  };
}

export interface WeeklyReport {
  weekNumber: number;
  year: number;
  startDate: string;
  endDate: string;
  metrics: CurrentMetrics;
  highlights: string[];
  concerns: string[];
  recommendations: string[];
}

class SuccessMetricsService {
  private readonly METRICS_COLLECTION = 'successMetrics';
  private readonly BASELINE_DOC_ID = 'baseline';
  private readonly WEEKLY_REPORTS_COLLECTION = 'weeklyReports';

  /**
   * Record baseline metrics before modernization
   */
  async recordBaseline(companyId: string): Promise<void> {
    console.log('[SuccessMetrics] Recording baseline metrics...');

    const baseline: BaselineMetrics = {
      timestamp: Date.now(),
      p95Latency: await this.measureP95Latency(),
      firestoreCosts: await this.measureFirestoreCosts(companyId),
      securityIncidents: await this.measureSecurityIncidents(companyId),
      codeQuality: await this.measureCodeQuality(),
    };

    // Save to Firestore
    const baselineRef = doc(
      db,
      `companies/${companyId}/${this.METRICS_COLLECTION}/${this.BASELINE_DOC_ID}`
    );
    await setDoc(baselineRef, baseline);

    console.log('[SuccessMetrics] Baseline recorded:', baseline);
  }

  /**
   * Get baseline metrics
   */
  async getBaseline(companyId: string): Promise<BaselineMetrics | null> {
    try {
      const baselineRef = doc(
        db,
        `companies/${companyId}/${this.METRICS_COLLECTION}/${this.BASELINE_DOC_ID}`
      );
      const snapshot = await getDoc(baselineRef);

      if (!snapshot.exists()) {
        return null;
      }

      return snapshot.data() as BaselineMetrics;
    } catch (error) {
      console.error('[SuccessMetrics] Failed to get baseline:', error);
      return null;
    }
  }

  /**
   * Measure current metrics and compare with baseline
   */
  async measureCurrentMetrics(companyId: string): Promise<CurrentMetrics | null> {
    const baseline = await this.getBaseline(companyId);

    if (!baseline) {
      console.warn('[SuccessMetrics] No baseline found. Record baseline first.');
      return null;
    }

    const current: BaselineMetrics = {
      timestamp: Date.now(),
      p95Latency: await this.measureP95Latency(),
      firestoreCosts: await this.measureFirestoreCosts(companyId),
      securityIncidents: await this.measureSecurityIncidents(companyId),
      codeQuality: await this.measureCodeQuality(),
    };

    // Calculate improvements
    const improvements = {
      p95LatencyReduction: this.calculateReduction(
        this.averageLatency(baseline.p95Latency),
        this.averageLatency(current.p95Latency)
      ),
      costReduction: this.calculateReduction(
        baseline.firestoreCosts.estimatedMonthlyCost,
        current.firestoreCosts.estimatedMonthlyCost
      ),
      securityIncidentsReduction: this.calculateReduction(
        this.totalSecurityIncidents(baseline.securityIncidents),
        this.totalSecurityIncidents(current.securityIncidents)
      ),
      codeQualityImprovement: this.calculateImprovement(
        this.averageCodeQuality(baseline.codeQuality),
        this.averageCodeQuality(current.codeQuality)
      ),
    };

    return {
      ...current,
      improvements,
    };
  }

  /**
   * Generate weekly report
   */
  async generateWeeklyReport(companyId: string): Promise<WeeklyReport> {
    const currentMetrics = await this.measureCurrentMetrics(companyId);

    if (!currentMetrics) {
      throw new Error('Cannot generate report without baseline metrics');
    }

    const now = new Date();
    const weekNumber = this.getWeekNumber(now);
    const year = now.getFullYear();
    const { startDate, endDate } = this.getWeekDates(now);

    // Generate highlights, concerns, and recommendations
    const highlights = this.generateHighlights(currentMetrics);
    const concerns = this.generateConcerns(currentMetrics);
    const recommendations = this.generateRecommendations(currentMetrics);

    const report: WeeklyReport = {
      weekNumber,
      year,
      startDate,
      endDate,
      metrics: currentMetrics,
      highlights,
      concerns,
      recommendations,
    };

    // Save report to Firestore
    const reportRef = doc(
      db,
      `companies/${companyId}/${this.WEEKLY_REPORTS_COLLECTION}/${year}_W${weekNumber}`
    );
    await setDoc(reportRef, {
      ...report,
      createdAt: Timestamp.now(),
    });

    console.log('[SuccessMetrics] Weekly report generated:', report);

    return report;
  }

  /**
   * Get all weekly reports
   */
  async getWeeklyReports(
    companyId: string,
    limitCount: number = 10
  ): Promise<WeeklyReport[]> {
    try {
      const reportsRef = collection(
        db,
        `companies/${companyId}/${this.WEEKLY_REPORTS_COLLECTION}`
      );
      const q = query(
        reportsRef,
        orderBy('createdAt', 'desc'),
        firestoreLimit(limitCount)
      );
      const snapshot = await getDocs(q);

      return snapshot.docs.map((doc) => doc.data() as WeeklyReport);
    } catch (error) {
      console.error('[SuccessMetrics] Failed to get weekly reports:', error);
      return [];
    }
  }

  /**
   * Get executive dashboard data
   */
  async getExecutiveDashboard(companyId: string): Promise<{
    baseline: BaselineMetrics | null;
    current: CurrentMetrics | null;
    recentReports: WeeklyReport[];
    summary: {
      overallProgress: number;
      targetsMet: number;
      targetsTotal: number;
      status: 'on-track' | 'at-risk' | 'off-track';
    };
  }> {
    const baseline = await this.getBaseline(companyId);
    const current = await this.measureCurrentMetrics(companyId);
    const recentReports = await this.getWeeklyReports(companyId, 4);

    // Calculate summary
    const summary = this.calculateSummary(current);

    return {
      baseline,
      current,
      recentReports,
      summary,
    };
  }

  /**
   * Measure P95 latency for critical operations
   */
  private async measureP95Latency(): Promise<BaselineMetrics['p95Latency']> {
    return {
      fetchOrders: PerformanceMonitoringService.getP95Latency('fetchOrders') || 0,
      createOrder: PerformanceMonitoringService.getP95Latency('createOrder') || 0,
      updateOrder: PerformanceMonitoringService.getP95Latency('updateOrder') || 0,
      deleteOrder: PerformanceMonitoringService.getP95Latency('deleteOrder') || 0,
      getDailySummary:
        PerformanceMonitoringService.getP95Latency('getDailySummary') || 0,
    };
  }

  /**
   * Measure Firestore costs
   */
  private async measureFirestoreCosts(
    companyId: string
  ): Promise<BaselineMetrics['firestoreCosts']> {
    const metrics = PerformanceMonitoringService.getFirestoreMetrics();

    // Firestore pricing (approximate):
    // Reads: $0.06 per 100,000 documents
    // Writes: $0.18 per 100,000 documents
    // Deletes: $0.02 per 100,000 documents

    const readCost = (metrics.reads / 100000) * 0.06;
    const writeCost = (metrics.writes / 100000) * 0.18;
    const deleteCost = (metrics.deletes / 100000) * 0.02;

    // Estimate monthly cost (assuming current rate continues)
    const dailyCost = readCost + writeCost + deleteCost;
    const estimatedMonthlyCost = dailyCost * 30;

    return {
      reads: metrics.reads,
      writes: metrics.writes,
      deletes: metrics.deletes,
      estimatedMonthlyCost,
    };
  }

  /**
   * Measure security incidents
   */
  private async measureSecurityIncidents(
    companyId: string
  ): Promise<BaselineMetrics['securityIncidents']> {
    // In a real implementation, this would query audit logs
    // For now, return mock data
    return {
      authFailures: 0,
      permissionDenied: 0,
      rateLimitViolations: 0,
      suspiciousActivity: 0,
    };
  }

  /**
   * Measure code quality metrics
   */
  private async measureCodeQuality(): Promise<BaselineMetrics['codeQuality']> {
    // In a real implementation, this would parse test coverage reports
    // and analyze codebase
    // For now, return estimated values
    return {
      testCoverage: 85, // percentage
      typeScriptAdoption: 90, // percentage
      lintErrors: 5,
      codeSmells: 10,
    };
  }

  /**
   * Calculate reduction percentage
   */
  private calculateReduction(baseline: number, current: number): number {
    if (baseline === 0) return 0;
    return ((baseline - current) / baseline) * 100;
  }

  /**
   * Calculate improvement percentage
   */
  private calculateImprovement(baseline: number, current: number): number {
    if (baseline === 0) return 0;
    return ((current - baseline) / baseline) * 100;
  }

  /**
   * Calculate average latency
   */
  private averageLatency(latency: BaselineMetrics['p95Latency']): number {
    const values = Object.values(latency);
    return values.reduce((sum, val) => sum + val, 0) / values.length;
  }

  /**
   * Calculate total security incidents
   */
  private totalSecurityIncidents(
    incidents: BaselineMetrics['securityIncidents']
  ): number {
    return Object.values(incidents).reduce((sum, val) => sum + val, 0);
  }

  /**
   * Calculate average code quality
   */
  private averageCodeQuality(quality: BaselineMetrics['codeQuality']): number {
    // Weighted average: coverage and TS adoption are positive, errors are negative
    return (
      (quality.testCoverage + quality.typeScriptAdoption) / 2 -
      (quality.lintErrors + quality.codeSmells) / 10
    );
  }

  /**
   * Generate highlights from metrics
   */
  private generateHighlights(metrics: CurrentMetrics): string[] {
    const highlights: string[] = [];

    if (metrics.improvements.p95LatencyReduction > 30) {
      highlights.push(
        `🚀 Latência P95 reduzida em ${metrics.improvements.p95LatencyReduction.toFixed(1)}%`
      );
    }

    if (metrics.improvements.costReduction > 50) {
      highlights.push(
        `💰 Custos Firestore reduzidos em ${metrics.improvements.costReduction.toFixed(1)}%`
      );
    }

    if (metrics.improvements.securityIncidentsReduction > 80) {
      highlights.push(
        `🔒 Incidentes de segurança reduzidos em ${metrics.improvements.securityIncidentsReduction.toFixed(1)}%`
      );
    }

    if (metrics.codeQuality.testCoverage > 80) {
      highlights.push(
        `✅ Cobertura de testes atingiu ${metrics.codeQuality.testCoverage}%`
      );
    }

    if (metrics.codeQuality.typeScriptAdoption > 85) {
      highlights.push(
        `📘 Adoção de TypeScript atingiu ${metrics.codeQuality.typeScriptAdoption}%`
      );
    }

    return highlights;
  }

  /**
   * Generate concerns from metrics
   */
  private generateConcerns(metrics: CurrentMetrics): string[] {
    const concerns: string[] = [];

    if (metrics.improvements.p95LatencyReduction < 10) {
      concerns.push('⚠️ Redução de latência abaixo do esperado (<10%)');
    }

    if (metrics.improvements.costReduction < 40) {
      concerns.push('⚠️ Redução de custos abaixo da meta de 60%');
    }

    if (this.totalSecurityIncidents(metrics.securityIncidents) > 10) {
      concerns.push('⚠️ Número elevado de incidentes de segurança');
    }

    if (metrics.codeQuality.testCoverage < 80) {
      concerns.push('⚠️ Cobertura de testes abaixo da meta de 80%');
    }

    if (metrics.codeQuality.lintErrors > 10) {
      concerns.push(`⚠️ ${metrics.codeQuality.lintErrors} erros de lint detectados`);
    }

    return concerns;
  }

  /**
   * Generate recommendations from metrics
   */
  private generateRecommendations(metrics: CurrentMetrics): string[] {
    const recommendations: string[] = [];

    if (metrics.improvements.p95LatencyReduction < 30) {
      recommendations.push(
        '💡 Implementar cache layer para reduzir latência de queries'
      );
    }

    if (metrics.improvements.costReduction < 60) {
      recommendations.push(
        '💡 Otimizar listeners real-time e implementar paginação'
      );
    }

    if (this.totalSecurityIncidents(metrics.securityIncidents) > 5) {
      recommendations.push('💡 Revisar security rules e implementar rate limiting');
    }

    if (metrics.codeQuality.testCoverage < 80) {
      recommendations.push('💡 Adicionar testes para módulos com baixa cobertura');
    }

    if (metrics.codeQuality.typeScriptAdoption < 90) {
      recommendations.push('💡 Migrar arquivos .js restantes para TypeScript');
    }

    return recommendations;
  }

  /**
   * Calculate overall summary
   */
  private calculateSummary(
    metrics: CurrentMetrics | null
  ): {
    overallProgress: number;
    targetsMet: number;
    targetsTotal: number;
    status: 'on-track' | 'at-risk' | 'off-track';
  } {
    if (!metrics) {
      return {
        overallProgress: 0,
        targetsMet: 0,
        targetsTotal: 5,
        status: 'off-track',
      };
    }

    const targets = [
      { name: 'P95 Latency', met: metrics.improvements.p95LatencyReduction >= 30 },
      { name: 'Cost Reduction', met: metrics.improvements.costReduction >= 60 },
      {
        name: 'Security',
        met: this.totalSecurityIncidents(metrics.securityIncidents) === 0,
      },
      { name: 'Test Coverage', met: metrics.codeQuality.testCoverage >= 80 },
      {
        name: 'TypeScript Adoption',
        met: metrics.codeQuality.typeScriptAdoption >= 90,
      },
    ];

    const targetsMet = targets.filter((t) => t.met).length;
    const targetsTotal = targets.length;
    const overallProgress = (targetsMet / targetsTotal) * 100;

    let status: 'on-track' | 'at-risk' | 'off-track';
    if (overallProgress >= 80) {
      status = 'on-track';
    } else if (overallProgress >= 50) {
      status = 'at-risk';
    } else {
      status = 'off-track';
    }

    return {
      overallProgress,
      targetsMet,
      targetsTotal,
      status,
    };
  }

  /**
   * Get week number of the year
   */
  private getWeekNumber(date: Date): number {
    const firstDayOfYear = new Date(date.getFullYear(), 0, 1);
    const pastDaysOfYear = (date.getTime() - firstDayOfYear.getTime()) / 86400000;
    return Math.ceil((pastDaysOfYear + firstDayOfYear.getDay() + 1) / 7);
  }

  /**
   * Get start and end dates of the week
   */
  private getWeekDates(date: Date): { startDate: string; endDate: string } {
    const day = date.getDay();
    const diff = date.getDate() - day + (day === 0 ? -6 : 1); // Adjust for Sunday

    const startDate = new Date(date.setDate(diff));
    const endDate = new Date(date.setDate(diff + 6));

    return {
      startDate: startDate.toISOString().split('T')[0],
      endDate: endDate.toISOString().split('T')[0],
    };
  }

  /**
   * Export metrics to JSON
   */
  async exportMetrics(companyId: string): Promise<string> {
    const dashboard = await this.getExecutiveDashboard(companyId);

    return JSON.stringify(
      {
        exportedAt: new Date().toISOString(),
        companyId,
        ...dashboard,
      },
      null,
      2
    );
  }
}

