/**
 * Connection Pool Manager
 * 
 * Manages database connections efficiently with pooling, health checks, and retry logic.
 * Provides connection lifecycle management with configurable timeouts and limits.
 * 
 * Requirements: 3.1, 3.2, 3.3, 3.4, 3.5, 3.7, 5.6, 11.3
 */

import { supabase } from '../../config/SupabaseConfig';
import type { PoolConfig, PoolStats, Connection } from '../../types/performance';

/**
 * Internal connection wrapper with metadata
 */
interface PooledConnection {
  id: string;
  connection: any;
  inUse: boolean;
  createdAt: Date;
  lastUsedAt: Date;
  healthCheckCount: number;
}

/**
 * Connection request in the waiting queue
 */
interface ConnectionRequest {
  resolve: (connection: Connection) => void;
  reject: (error: Error) => void;
  timestamp: Date;
}

/**
 * Default pool configuration
 * Requirements: 3.1, 3.2, 3.3
 */
const DEFAULT_CONFIG: PoolConfig = {
  minConnections: 5,
  maxConnections: 20,
  idleTimeout: 60000, // 60 seconds
  connectionTimeout: 5000, // 5 seconds
  retryAttempts: 3,
  retryDelay: 1000, // 1 second base delay
};

/**
 * Connection Pool Manager Service
 * 
 * Manages a pool of database connections with:
 * - Min/max connection limits (5-20)
 * - Connection lifecycle management
 * - Health checks and validation
 * - Retry logic with exponential backoff
 * - Metrics tracking
 */
export class ConnectionPoolManager {
  private config: PoolConfig;
  private pool: PooledConnection[] = [];
  private waitingQueue: ConnectionRequest[] = [];
  private stats = {
    active: 0,
    idle: 0,
    waiting: 0,
    total: 0,
    utilization: 0,
  };
  private cleanupInterval?: NodeJS.Timeout;
  private initialized = false;

  constructor(config?: Partial<PoolConfig>) {
    this.config = { ...DEFAULT_CONFIG, ...config };
  }

  /**
   * Initialize the connection pool
   * Creates minimum number of connections
   */
  async initialize(): Promise<void> {
    if (this.initialized) {
      return;
    }

    // Create minimum connections
    const promises: Promise<void>[] = [];
    for (let i = 0; i < this.config.minConnections; i++) {
      promises.push(this.createConnection());
    }

    await Promise.all(promises);

    // Start cleanup interval for idle connections
    this.startCleanupInterval();

    this.initialized = true;
  }

  /**
   * Get a connection from the pool
   * Requirements: 3.2, 3.7
   * 
   * @returns Promise<Connection> - A database connection
   * @throws Error if connection timeout is reached
   */
  async getConnection(): Promise<Connection> {
    // Find an idle connection
    const pooledConn = this.pool.find(c => !c.inUse);

    if (pooledConn) {
      // Mark as in use
      pooledConn.inUse = true;
      pooledConn.lastUsedAt = new Date();
      this.updateStats();

      // Validate connection health
      const isHealthy = await this.validateConnection(pooledConn);
      if (!isHealthy) {
        // Remove unhealthy connection and create a new one
        await this.removeConnection(pooledConn.id);
        return this.getConnection(); // Retry
      }

      return this.wrapConnection(pooledConn);
    }

    // No idle connections available
    if (this.pool.length < this.config.maxConnections) {
      // Create a new connection
      await this.createConnection();
      return this.getConnection(); // Retry with new connection
    }

    // Pool is exhausted, queue the request
    return this.queueConnectionRequest();
  }

  /**
   * Release a connection back to the pool
   * Requirements: 3.2
   * 
   * @param connection - The connection to release
   */
  releaseConnection(connectionId: string): void {
    const pooledConn = this.pool.find(c => c.id === connectionId);

    if (pooledConn) {
      pooledConn.inUse = false;
      pooledConn.lastUsedAt = new Date();
      this.updateStats();

      // Process waiting queue
      this.processWaitingQueue();
    }
  }

  /**
   * Execute a query with automatic connection management
   * Requirements: 3.7
   * 
   * @param query - SQL query string
   * @param params - Query parameters
   * @returns Promise<T> - Query result
   */
  async executeQuery<T = any>(query: string, params?: any[]): Promise<T> {
    const connection = await this.getConnection();

    try {
      const result = await connection.query<T>(query, params);
      return result;
    } finally {
      connection.release();
    }
  }

  /**
   * Get pool statistics
   * Requirements: 3.5, 11.3
   * 
   * @returns PoolStats - Current pool statistics
   */
  getPoolStats(): PoolStats {
    return { ...this.stats };
  }

  /**
   * Configure pool settings
   * 
   * @param config - Partial pool configuration
   */
  configure(config: Partial<PoolConfig>): void {
    this.config = { ...this.config, ...config };
  }

  /**
   * Shutdown the pool and close all connections
   */
  async shutdown(): Promise<void> {
    if (this.cleanupInterval) {
      clearInterval(this.cleanupInterval);
    }

    // Close all connections
    const promises = this.pool.map(c => this.removeConnection(c.id));
    await Promise.all(promises);

    // Reject all waiting requests
    this.waitingQueue.forEach(req => {
      req.reject(new Error('Connection pool is shutting down'));
    });
    this.waitingQueue = [];

    this.initialized = false;
  }

  // ============================================================================
  // Private Methods
  // ============================================================================

  /**
   * Create a new connection with retry logic
   * Requirements: 3.4, 5.6
   */
  private async createConnection(attempt = 0): Promise<void> {
    try {
      // For Supabase, we use the client directly
      // In a real implementation with direct PostgreSQL, you would create a pg.Client here
      const connection = supabase;

      const pooledConn: PooledConnection = {
        id: this.generateConnectionId(),
        connection,
        inUse: false,
        createdAt: new Date(),
        lastUsedAt: new Date(),
        healthCheckCount: 0,
      };

      this.pool.push(pooledConn);
      this.updateStats();
    } catch (error) {
      // Retry with exponential backoff
      if (attempt < this.config.retryAttempts) {
        const delay = this.calculateBackoffDelay(attempt);
        await this.sleep(delay);
        return this.createConnection(attempt + 1);
      }

      throw new Error(`Failed to create connection after ${this.config.retryAttempts} attempts: ${error}`);
    }
  }

  /**
   * Remove a connection from the pool
   */
  private async removeConnection(connectionId: string): Promise<void> {
    const index = this.pool.findIndex(c => c.id === connectionId);

    if (index !== -1) {
      const pooledConn = this.pool[index];

      // For Supabase client, we don't need to explicitly close
      // In a real pg.Client implementation, you would call client.end() here

      this.pool.splice(index, 1);
      this.updateStats();
    }
  }

  /**
   * Validate connection health
   * Requirements: 3.2
   */
  private async validateConnection(pooledConn: PooledConnection): Promise<boolean> {
    try {
      // Simple health check query
      const { error } = await pooledConn.connection
        .from('companies')
        .select('id')
        .limit(1)
        .single();

      pooledConn.healthCheckCount++;

      // Consider connection healthy if no error or if it's just "no rows" error
      return !error || error.code === 'PGRST116';
    } catch (error) {
      return false;
    }
  }

  /**
   * Wrap a pooled connection for external use
   */
  private wrapConnection(pooledConn: PooledConnection): Connection {
    return {
      query: async <T = any>(sql: string, params?: any[]): Promise<T> => {
        // For Supabase, we execute raw SQL using rpc or direct queries
        // This is a simplified implementation
        const { data, error } = await pooledConn.connection.rpc('execute_sql', {
          query: sql,
          params: params || [],
        });

        if (error) {
          throw error;
        }

        return data as T;
      },
      release: () => {
        this.releaseConnection(pooledConn.id);
      },
    };
  }

  /**
   * Queue a connection request when pool is exhausted
   * Requirements: 3.2, 3.3
   */
  private queueConnectionRequest(): Promise<Connection> {
    return new Promise((resolve, reject) => {
      const request: ConnectionRequest = {
        resolve,
        reject,
        timestamp: new Date(),
      };

      this.waitingQueue.push(request);
      this.updateStats();

      // Set timeout for the request
      setTimeout(() => {
        const index = this.waitingQueue.indexOf(request);
        if (index !== -1) {
          this.waitingQueue.splice(index, 1);
          this.updateStats();
          reject(new Error('Connection request timeout'));
        }
      }, this.config.connectionTimeout);
    });
  }

  /**
   * Process waiting queue when connections become available
   */
  private async processWaitingQueue(): Promise<void> {
    if (this.waitingQueue.length === 0) {
      return;
    }

    const request = this.waitingQueue.shift();
    if (request) {
      this.updateStats();

      try {
        const connection = await this.getConnection();
        request.resolve(connection);
      } catch (error) {
        request.reject(error as Error);
      }
    }
  }

  /**
   * Start cleanup interval for idle connections
   * Requirements: 3.3
   */
  private startCleanupInterval(): void {
    // Only start if not already running
    if (this.cleanupInterval) {
      return;
    }

    this.cleanupInterval = setInterval(() => {
      this.cleanupIdleConnections();
    }, 30000); // Check every 30 seconds

    // Unref the interval so it doesn't keep the process alive
    if (this.cleanupInterval.unref) {
      this.cleanupInterval.unref();
    }
  }

  /**
   * Clean up idle connections that exceed idle timeout
   * Requirements: 3.3
   */
  private async cleanupIdleConnections(): Promise<void> {
    const now = Date.now();
    const idleConnections = this.pool.filter(c => {
      if (c.inUse) return false;

      const idleTime = now - c.lastUsedAt.getTime();
      return idleTime > this.config.idleTimeout;
    });

    // Keep minimum connections
    const connectionsToRemove = Math.max(
      0,
      this.pool.length - idleConnections.length - this.config.minConnections
    );

    for (let i = 0; i < Math.min(connectionsToRemove, idleConnections.length); i++) {
      await this.removeConnection(idleConnections[i].id);
    }
  }

  /**
   * Update pool statistics
   * Requirements: 3.5, 11.3
   */
  private updateStats(): void {
    this.stats.active = this.pool.filter(c => c.inUse).length;
    this.stats.idle = this.pool.filter(c => !c.inUse).length;
    this.stats.waiting = this.waitingQueue.length;
    this.stats.total = this.pool.length;
    this.stats.utilization = this.stats.total > 0 
      ? (this.stats.active / this.stats.total) * 100 
      : 0;
  }

  /**
   * Calculate exponential backoff delay
   * Requirements: 3.4, 5.6
   * 
   * @param attempt - Current retry attempt number
   * @returns Delay in milliseconds
   */
  private calculateBackoffDelay(attempt: number): number {
    const baseDelay = this.config.retryDelay;
    const maxDelay = 30000; // 30 seconds max
    const delay = Math.min(baseDelay * Math.pow(2, attempt), maxDelay);
    return delay;
  }

  /**
   * Generate unique connection ID
   */
  private generateConnectionId(): string {
    return `conn_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }

  /**
   * Sleep utility for delays
   */
  private sleep(ms: number): Promise<void> {
    return new Promise(resolve => setTimeout(resolve, ms));
  }
}

// Singleton instance
export const connectionPoolManager = new ConnectionPoolManager();

/**
 * Cursor-Based Pagination Service for Supabase
 * 
 * Implements efficient cursor-based pagination that:
 * - Avoids OFFSET (which causes full table scans)
 * - Uses indexed columns for cursor keys
 * - Limits page size to maximum 50 records
 * - Validates cursor integrity
 * - Provides count estimation without full scans
 * 
 * Requirements: 9.1, 9.2, 9.3, 9.4, 9.5, 9.6, 9.7
 */

import { SupabaseClient } from '@supabase/supabase-js';
import { supabase } from '../../config/SupabaseConfig';

/**
 * Pagination configuration
 */
export interface PaginationConfig {
  maxPageSize: number;
  defaultPageSize: number;
}

/**
 * Cursor for pagination
 */
export interface PaginationCursor {
  value: any;
  column: string;
  direction: 'asc' | 'desc';
  timestamp: number;
  signature: string;
}

/**
 * Pagination result
 */
export interface PaginationResult<T> {
  items: T[];
  nextCursor: string | null;
  prevCursor: string | null;
  hasMore: boolean;
  pageSize: number;
  estimatedTotal?: number;
}

/**
 * Pagination options
 */
export interface PaginationOptions {
  pageSize?: number;
  cursor?: string;
  orderBy?: string;
  orderDirection?: 'asc' | 'desc';
  filters?: Record<string, any>;
}

/**
 * Cursor-Based Pagination Service
 */
export class CursorPaginationService {
  private config: PaginationConfig = {
    maxPageSize: 50,
    defaultPageSize: 20
  };

  private client: SupabaseClient;
  private secret: string = 'cursor-secret-key'; // In production, use env variable

  constructor(client?: SupabaseClient) {
    this.client = client || supabase;
  }

  /**
   * Paginate query results using cursor-based pagination
   * Requirement 9.1: Use cursor-based pagination
   * Requirement 9.3: Use indexed columns for cursor keys
   * Requirement 9.4: Avoid OFFSET
   */
  async paginate<T = any>(
    table: string,
    options: PaginationOptions = {}
  ): Promise<PaginationResult<T>> {
    // Requirement 9.2: Limit page size to maximum 50 records
    const pageSize = this.enforcePageSizeLimit(options.pageSize);
    const orderBy = options.orderBy || 'created_at';
    const orderDirection = options.orderDirection || 'desc';

    // Build query
    let query = this.client
      .from(table)
      .select('*', { count: 'estimated' });

    // Apply filters
    if (options.filters) {
      Object.entries(options.filters).forEach(([key, value]) => {
        query = query.eq(key, value);
      });
    }

    // Apply cursor if provided
    if (options.cursor) {
      const decodedCursor = this.decodeCursor(options.cursor);

      // Requirement 9.5: Validate cursor integrity
      if (!this.validateCursor(decodedCursor)) {
        throw new Error('Invalid or tampered cursor');
      }

      // Apply cursor filter using indexed column
      const operator = orderDirection === 'desc' ? 'lt' : 'gt';
      query = query[operator](orderBy, decodedCursor.value);
    }

    // Apply ordering and limit
    query = query
      .order(orderBy, { ascending: orderDirection === 'asc' })
      .limit(pageSize + 1); // Fetch one extra to check if there are more

    // Execute query
    const { data, error, count } = await query;

    if (error) {
      throw new Error(`Pagination query failed: ${error.message}`);
    }

    const items = data || [];
    const hasMore = items.length > pageSize;

    // Remove extra item if present
    if (hasMore) {
      items.pop();
    }

    // Generate next cursor
    const nextCursor = hasMore && items.length > 0
      ? this.encodeCursor({
          value: items[items.length - 1][orderBy],
          column: orderBy,
          direction: orderDirection,
          timestamp: Date.now()
        })
      : null;

    // Generate previous cursor (for backward pagination)
    const prevCursor = items.length > 0 && options.cursor
      ? this.encodeCursor({
          value: items[0][orderBy],
          column: orderBy,
          direction: orderDirection === 'desc' ? 'asc' : 'desc',
          timestamp: Date.now()
        })
      : null;

    return {
      items: items as T[],
      nextCursor,
      prevCursor,
      hasMore,
      pageSize: items.length,
      estimatedTotal: count || undefined
    };
  }

  /**
   * Requirement 9.2: Enforce maximum page size of 50 records
   */
  private enforcePageSizeLimit(requestedSize?: number): number {
    if (!requestedSize) {
      return this.config.defaultPageSize;
    }

    if (requestedSize > this.config.maxPageSize) {
      return this.config.maxPageSize;
    }

    if (requestedSize < 1) {
      return this.config.defaultPageSize;
    }

    return requestedSize;
  }

  /**
   * Encode cursor to base64 string with signature
   */
  private encodeCursor(cursor: Omit<PaginationCursor, 'signature'>): string {
    const cursorWithSignature: PaginationCursor = {
      ...cursor,
      signature: this.generateSignature(cursor)
    };

    const json = JSON.stringify(cursorWithSignature);
    return Buffer.from(json).toString('base64');
  }

  /**
   * Decode cursor from base64 string
   */
  private decodeCursor(encodedCursor: string): PaginationCursor {
    try {
      const json = Buffer.from(encodedCursor, 'base64').toString('utf-8');
      return JSON.parse(json);
    } catch (error) {
      throw new Error('Invalid cursor format');
    }
  }

  /**
   * Requirement 9.5: Validate cursor integrity
   * Reject invalid or tampered cursors
   */
  private validateCursor(cursor: PaginationCursor): boolean {
    // Check required fields
    if (!cursor.value || !cursor.column || !cursor.direction || !cursor.timestamp || !cursor.signature) {
      return false;
    }

    // Check timestamp (reject cursors older than 1 hour)
    const oneHourAgo = Date.now() - (60 * 60 * 1000);
    if (cursor.timestamp < oneHourAgo) {
      return false;
    }

    // Verify signature
    const expectedSignature = this.generateSignature({
      value: cursor.value,
      column: cursor.column,
      direction: cursor.direction,
      timestamp: cursor.timestamp
    });

    return cursor.signature === expectedSignature;
  }

  /**
   * Generate signature for cursor integrity
   */
  private generateSignature(cursor: Omit<PaginationCursor, 'signature'>): string {
    const data = `${cursor.value}:${cursor.column}:${cursor.direction}:${cursor.timestamp}:${this.secret}`;

    // Simple hash function (in production, use crypto.createHmac)
    let hash = 0;
    for (let i = 0; i < data.length; i++) {
      const char = data.charCodeAt(i);
      hash = ((hash << 5) - hash) + char;
      hash = hash & hash;
    }

    return hash.toString(36);
  }

  /**
   * Requirement 9.6: Get count estimation without full table scans
   * Uses pg_class statistics for fast estimation
   */
  async getEstimatedCount(table: string, filters?: Record<string, any>): Promise<number> {
    try {
      // Try to get estimated count from pg_class
      const { data, error } = await this.client.rpc('get_estimated_count', {
        table_name: table
      });

      if (!error && data) {
        return data;
      }

      // Fallback: use Supabase's count with 'estimated' hint
      let query = this.client
        .from(table)
        .select('*', { count: 'estimated', head: true });

      if (filters) {
        Object.entries(filters).forEach(([key, value]) => {
          query = query.eq(key, value);
        });
      }

      const { count } = await query;
      return count || 0;
    } catch (error) {
      console.warn('Failed to get estimated count:', error);
      return 0;
    }
  }

  /**
   * Configure pagination settings
   */
  configure(config: Partial<PaginationConfig>): void {
    this.config = { ...this.config, ...config };
  }

  /**
   * Get current configuration
   */
  getConfig(): PaginationConfig {
    return { ...this.config };
  }
}

