  invalidateAllOrders(companyId: string) {
    this.deduplicator.invalidatePattern(`orders.*${companyId}`);
  }

  /**
   * Get deduplication metrics
   */
  getMetrics() {
    return this.deduplicator.getMetrics();
  }
}

