import { Platform, Alert, BackHandler } from 'react-native';

/**
 * Força reinicialização completa do app
 * Solução definitiva para problemas de logout/tela branca
 */
export const forceAppRestart = async () => {
  try {
    if (Platform.OS === 'android') {
      // Método 1: Tentar usar expo-updates
      try {
        const { Updates } = require('expo-updates');
        await Updates.reloadAsync();
        return;
      } catch (updateError) {
        console.log('expo-updates não disponível, usando método alternativo');
      }

      // Método 2: Fechar app no Android
      try {
        BackHandler.exitApp();
        return;
      } catch (backError) {
        console.log('BackHandler.exitApp falhou');
      }

      // Método 3: Tentar RNRestart se disponível
      try {
        const RNRestart = require('react-native-restart');
        RNRestart.Restart();
        return;
      } catch (restartError) {
        console.log('react-native-restart não disponível');
      }
    }

    // Fallback: Mostrar alerta para reiniciar manualmente
    Alert.alert(
      'Reiniciar App', 
      'Por favor, feche e abra o app novamente para completar o logout.',
      [{ text: 'OK' }]
    );

  } catch (error) {
    console.error('Erro ao reiniciar app:', error);
    Alert.alert(
      'Reiniciar App', 
      'Por favor, feche e abra o app novamente.',
      [{ text: 'OK' }]
    );
  }
};

/**
 * Logout com reinicialização forçada
 * Garante que o app volte ao estado inicial
 */
export const logoutWithRestart = async (firebaseSignOut) => {
  try {
    // 1. Fazer signOut do Firebase primeiro
    await firebaseSignOut();

    // 2. Aguardar um pouco para garantir que o signOut foi processado
    await new Promise(resolve => setTimeout(resolve, 500));

    // 3. Forçar reinicialização completa
    await forceAppRestart();

  } catch (error) {
    console.error('Erro no logout com restart:', error);
    // Mesmo com erro, tentar reiniciar
    await forceAppRestart();
  }
};

/**
 * Cursor Validation Utility
 * 
 * Provides cursor validation logic for pagination
 * Requirement 9.5: Reject invalid or tampered cursors
 */

import crypto from 'crypto';

export interface CursorData {
  value: any;
  column: string;
  direction: 'asc' | 'desc';
  timestamp: number;
  signature: string;
}

export interface CursorValidationResult {
  valid: boolean;
  error?: string;
}

/**
 * Cursor Validator
 */
export class CursorValidator {
  private secret: string;
  private maxAge: number; // in milliseconds

  constructor(secret?: string, maxAgeHours: number = 1) {
    this.secret = secret || process.env.CURSOR_SECRET || 'default-cursor-secret';
    this.maxAge = maxAgeHours * 60 * 60 * 1000;
  }

  /**
   * Validate cursor integrity and freshness
   * Requirement 9.5: Reject invalid or tampered cursors
   */
  validate(encodedCursor: string): CursorValidationResult {
    try {
      // Decode cursor
      const cursor = this.decode(encodedCursor);

      // Validate structure
      if (!this.hasRequiredFields(cursor)) {
        return {
          valid: false,
          error: 'Cursor missing required fields'
        };
      }

      // Validate timestamp (reject old cursors)
      if (!this.isTimestampValid(cursor.timestamp)) {
        return {
          valid: false,
          error: 'Cursor expired'
        };
      }

      // Validate signature (detect tampering)
      if (!this.isSignatureValid(cursor)) {
        return {
          valid: false,
          error: 'Cursor signature invalid - possible tampering detected'
        };
      }

      return { valid: true };
    } catch (error) {
      return {
        valid: false,
        error: `Cursor validation failed: ${error instanceof Error ? error.message : 'Unknown error'}`
      };
    }
  }

  /**
   * Encode cursor data to base64 string with signature
   */
  encode(data: Omit<CursorData, 'signature'>): string {
    const signature = this.generateSignature(data);
    const cursorWithSignature: CursorData = {
      ...data,
      signature
    };

    const json = JSON.stringify(cursorWithSignature);
    return Buffer.from(json).toString('base64');
  }

  /**
   * Decode cursor from base64 string
   */
  decode(encodedCursor: string): CursorData {
    try {
      const json = Buffer.from(encodedCursor, 'base64').toString('utf-8');
      const cursor = JSON.parse(json);

      if (typeof cursor !== 'object' || cursor === null) {
        throw new Error('Invalid cursor format');
      }

      return cursor as CursorData;
    } catch (error) {
      throw new Error('Failed to decode cursor');
    }
  }

  /**
   * Check if cursor has all required fields
   */
  private hasRequiredFields(cursor: any): cursor is CursorData {
    return (
      cursor &&
      typeof cursor === 'object' &&
      'value' in cursor &&
      'column' in cursor &&
      'direction' in cursor &&
      'timestamp' in cursor &&
      'signature' in cursor &&
      typeof cursor.column === 'string' &&
      (cursor.direction === 'asc' || cursor.direction === 'desc') &&
      typeof cursor.timestamp === 'number' &&
      typeof cursor.signature === 'string'
    );
  }

  /**
   * Validate cursor timestamp
   */
  private isTimestampValid(timestamp: number): boolean {
    const now = Date.now();
    const age = now - timestamp;

    // Reject future timestamps
    if (timestamp > now) {
      return false;
    }

    // Reject expired cursors
    if (age > this.maxAge) {
      return false;
    }

    return true;
  }

  /**
   * Validate cursor signature
   */
  private isSignatureValid(cursor: CursorData): boolean {
    const expectedSignature = this.generateSignature({
      value: cursor.value,
      column: cursor.column,
      direction: cursor.direction,
      timestamp: cursor.timestamp
    });

    return cursor.signature === expectedSignature;
  }

  /**
   * Generate HMAC signature for cursor
   */
  private generateSignature(data: Omit<CursorData, 'signature'>): string {
    const payload = JSON.stringify({
      value: data.value,
      column: data.column,
      direction: data.direction,
      timestamp: data.timestamp
    });

    // Use HMAC-SHA256 for signature
    const hmac = crypto.createHmac('sha256', this.secret);
    hmac.update(payload);
    return hmac.digest('hex');
  }

  /**
   * Set secret key for signature generation
   */
  setSecret(secret: string): void {
    this.secret = secret;
  }

  /**
   * Set maximum cursor age in hours
   */
  setMaxAge(hours: number): void {
    this.maxAge = hours * 60 * 60 * 1000;
  }
}

// Singleton instance
export const cursorValidator = new CursorValidator();

/**
 * Convenience function to validate cursor
 */
export function validateCursor(encodedCursor: string): CursorValidationResult {
  return cursorValidator.validate(encodedCursor);
}

/**
 * Convenience function to encode cursor
 */
export function encodeCursor(data: Omit<CursorData, 'signature'>): string {
  return cursorValidator.encode(data);
}

/**
 * Convenience function to decode cursor
 */
export function decodeCursor(encodedCursor: string): CursorData {
  return cursorValidator.decode(encodedCursor);
}

import { Alert } from 'react-native';

/**
 * Robust Error Handling Utilities
 * Provides retry mechanisms, network error handling, and user-friendly error messages
 */

/**
 * Retry a function with exponential backoff
 * @param {Function} fn - Function to retry
 * @param {Object} options - Retry options
 * @returns {Promise} Result of the function or throws final error
 */
export const retryWithBackoff = async (fn, options = {}) => {
  const {
    maxRetries = 3,
    initialDelay = 1000,
    maxDelay = 10000,
    backoffFactor = 2,
    retryCondition = (error) => isRetryableError(error)
  } = options;

  let lastError;
  let delay = initialDelay;

  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      return await fn();
    } catch (error) {
      lastError = error;

      // Don't retry on last attempt or if error is not retryable
      if (attempt === maxRetries || !retryCondition(error)) {
        break;
      }

      // Wait before retrying
      await new Promise(resolve => setTimeout(resolve, delay));

      // Increase delay for next attempt (exponential backoff)
      delay = Math.min(delay * backoffFactor, maxDelay);
    }
  }

  throw lastError;
};

/**
 * Determines if an error is retryable
 * @param {Error} error - Error to check
 * @returns {boolean} True if error should be retried
 */
export const isRetryableError = (error) => {
  if (!error) return false;

  // Network errors
  if (error.code === 'unavailable' || 
      error.code === 'deadline-exceeded' ||
      error.code === 'resource-exhausted') {
    return true;
  }

  // Connection errors
  if (error.message && (
      error.message.includes('network') ||
      error.message.includes('timeout') ||
      error.message.includes('connection') ||
      error.message.includes('NETWORK_ERROR') ||
      error.message.includes('fetch')
  )) {
    return true;
  }

  // Firestore specific retryable errors
  if (error.code === 'aborted' || error.code === 'internal') {
    return true;
  }

  return false;
};

/**
 * Wraps a Firestore query with robust error handling
 * @param {Function} queryFn - Function that performs the query
 * @param {Object} options - Error handling options
 * @returns {Promise} Query result or throws user-friendly error
 */
export const robustFirestoreQuery = async (queryFn, options = {}) => {
  const {
    fallbackFn = null,
    userFriendlyMessage = 'Não foi possível carregar os dados. Tente novamente.',
    maxRetries = 2
  } = options;

  try {
    return await retryWithBackoff(queryFn, { maxRetries });
  } catch (error) {
    console.error('[RobustQuery] Error after retries:', error);

    // Try fallback if provided
    if (fallbackFn) {
      try {
        console.log('[RobustQuery] Attempting fallback...');
        return await fallbackFn();
      } catch (fallbackError) {
        console.error('[RobustQuery] Fallback also failed:', fallbackError);
      }
    }

    // Throw user-friendly error
    throw new Error(userFriendlyMessage);
  }
};

/**
 * Creates a user-friendly error message based on the error type
 * @param {Error} error - Original error
 * @param {string} context - Context where error occurred
 * @returns {string} User-friendly error message
 */
export const createUserFriendlyErrorMessage = (error, context = '') => {
  if (!error) return 'Ocorreu um erro inesperado.';

  // Network connectivity issues
  if (error.code === 'unavailable' || 
      (error.message && error.message.includes('network'))) {
    return 'Problema de conexão. Verifique sua internet e tente novamente.';
  }

  // Permission issues
  if (error.code === 'permission-denied') {
    return 'Você não tem permissão para realizar esta ação.';
  }

  // Not found errors
  if (error.code === 'not-found') {
    return context ? `${context} não encontrado(a).` : 'Item não encontrado.';
  }

  // Timeout errors
  if (error.code === 'deadline-exceeded' || 
      (error.message && error.message.includes('timeout'))) {
    return 'A operação demorou muito para responder. Tente novamente.';
  }

  // Firestore index errors
  if (error.code === 'failed-precondition' || 
      (error.message && error.message.includes('index'))) {
    return 'Sistema temporariamente indisponível. Tente novamente em alguns minutos.';
  }

  // Generic fallback
  return error.message || 'Ocorreu um erro inesperado. Tente novamente.';
};

/**
 * Wraps a function with comprehensive error handling and user feedback
 * @param {Function} fn - Function to wrap
 * @param {Object} options - Error handling options
 * @returns {Function} Wrapped function
 */
export const withErrorHandling = (fn, options = {}) => {
  const {
    context = '',
    showAlert = true,
    fallbackValue = null,
    onError = null
  } = options;

  return async (...args) => {
    try {
      return await fn(...args);
    } catch (error) {
      console.error(`[${context}] Error:`, error);

      const userMessage = createUserFriendlyErrorMessage(error, context);

      if (showAlert && typeof Alert !== 'undefined') {
        Alert.alert('Erro', userMessage);
      }

      if (onError) {
        onError(error, userMessage);
      }

      if (fallbackValue !== null) {
        return fallbackValue;
      }

      throw error;
    }
  };
};

/**
 * Validates network connectivity before performing operations
 * @returns {Promise<boolean>} True if network is available
 */
export const checkNetworkConnectivity = async () => {
  try {
    // Simple connectivity check - try to reach a reliable endpoint
    const response = await fetch('https://www.google.com/favicon.ico', {
      method: 'HEAD',
      mode: 'no-cors',
      cache: 'no-cache',
      timeout: 5000
    });
    return true;
  } catch (error) {
    console.warn('[NetworkCheck] No connectivity detected:', error.message);
    return false;
  }
};

/**
 * Enhanced query builder with automatic fallbacks
 * @param {Object} primaryQuery - Primary query configuration
 * @param {Array} fallbackQueries - Array of fallback query configurations
 * @returns {Promise} Query result
 */
export const queryWithFallbacks = async (primaryQuery, fallbackQueries = []) => {
  const queries = [primaryQuery, ...fallbackQueries];
  let lastError;

  for (let i = 0; i < queries.length; i++) {
    const queryConfig = queries[i];
    const isLastQuery = i === queries.length - 1;

    try {
      console.log(`[QueryFallback] Attempting query ${i + 1}/${queries.length}`);
      return await queryConfig.execute();
    } catch (error) {
      lastError = error;
      console.warn(`[QueryFallback] Query ${i + 1} failed:`, error.message);

      // If this is the last query or error is not retryable, don't continue
      if (isLastQuery || !isRetryableError(error)) {
        break;
      }
    }
  }

  throw lastError || new Error('All query attempts failed');
};

/**
 * Field Migration Helpers
 * 
 * Helpers para facilitar migração gradual de campos deprecated.
 * Permite código funcionar com ambos os campos durante período de transição.
 * 
 * Requirements: 15.3, 15.4
 */

/**
 * Obtém comandaNumber de um objeto, suportando ambos os campos
 * Prioriza campo novo (comandaNumber), mas aceita deprecated (numeroComanda)
 */
export function getComandaNumber(data: any): string {
  return data.comandaNumber || data.numeroComanda || '';
}

/**
 * Obtém createdBy de um objeto, suportando ambos os campos
 * Prioriza campo novo (createdBy), mas aceita deprecated (criadoPor)
 */
export function getCreatedBy(data: any): string {
  return data.createdBy || data.criadoPor || '';
}

/**
 * Cria objeto com ambos os campos para compatibilidade durante migração
 * Usa campo normalizado como fonte de verdade
 */
export function createCompatibleOrderFields(data: {
  comandaNumber: string;
  createdBy: string;
}): {
  comandaNumber: string;
  createdBy: string;
  // Campos deprecated para compatibilidade
  numeroComanda?: string;
  criadoPor?: string;
} {
  return {
    comandaNumber: data.comandaNumber,
    createdBy: data.createdBy,
    // Mantém campos deprecated durante período de transição
    numeroComanda: data.comandaNumber,
    criadoPor: data.createdBy
  };
}

/**
 * Remove campos deprecated de um objeto
 * Útil para limpeza após migração
 */
export function removeDeprecatedFields(data: any): any {
  const { numeroComanda, criadoPor, ...rest } = data;
  return rest;
}

/**
 * Verifica se objeto tem apenas campos normalizados (sem deprecated)
 */
export function hasOnlyNormalizedFields(data: any): boolean {
  return (
    data.comandaNumber !== undefined &&
    data.createdBy !== undefined &&
    data.numeroComanda === undefined &&
    data.criadoPor === undefined
  );
}

/**
 * Migra campos de um objeto in-place
 * Útil para processar dados antes de salvar
 */
export function migrateFieldsInPlace(data: any): void {
  // Migra numeroComanda → comandaNumber
  if (data.numeroComanda && !data.comandaNumber) {
    data.comandaNumber = data.numeroComanda;
  }

  // Migra criadoPor → createdBy
  if (data.criadoPor && !data.createdBy) {
    data.createdBy = data.criadoPor;
  }
}

export const FieldMigrationHelpers = {
  getComandaNumber,
  getCreatedBy,
  createCompatibleOrderFields,
  removeDeprecatedFields,
  hasOnlyNormalizedFields,
  migrateFieldsInPlace
};

/**
 * Supabase Data Converter - Optimized
 * 
 * Implements optimized data conversion with:
 * - Memoization to avoid re-processing
 * - Shallow comparison to detect changes
 * - Selective transformation of changed fields only
 * - TypeScript interfaces for type safety
 * - Support for legacy field migration
 * 
 * Requirements: 11.1, 11.2, 11.3, 11.4, 11.5, 15.3
 */

import { getComandaNumber, getCreatedBy } from './fieldMigrationHelpers';

/**
 * Memoized conversion cache
 */
interface ConversionCache {
  hash: string;
  result: any;
  timestamp: number;
}

/**
 * Supabase Converter with memoization
 */
class SupabaseConverter {
  private cache: Map<string, ConversionCache> = new Map();
  private readonly CACHE_TTL = 60 * 1000; // 1 minute

  /**
   * Converts Supabase row to Order with memoization
   */
  supabaseToOrder(row: any, rowId: string): any {
    const cacheKey = `order:${rowId}`;

    // Calculate data hash
    const dataHash = this.calculateHash(row);

    // Check cache
    const cached = this.cache.get(cacheKey);
    if (cached && cached.hash === dataHash) {
      // Cache hit - return memoized result
      return cached.result;
    }

    // Cache miss - convert data
    const result = this.convertOrderData(row, rowId);

    // Store in cache
    this.cache.set(cacheKey, {
      hash: dataHash,
      result,
      timestamp: Date.now()
    });

    return result;
  }

  /**
   * Converts order data
   * Uses helpers to support deprecated fields during migration
   */
  private convertOrderData(row: any, rowId: string): any {
    return {
      id: rowId,
      companyId: row.company_id || row.companyId || '',
      comandaNumber: getComandaNumber(row), // Supports both fields
      dateKey: row.date_key || row.dateKey || '',
      status: row.status || 'pending',
      items: this.convertItems(row.items || row.itens || []),
      totalAmount: row.total_amount || row.totalAmount || row.total || 0,
      isPago: row.is_pago || row.isPago || false,
      createdBy: getCreatedBy(row), // Supports both fields
      createdAt: this.convertTimestamp(row.created_at || row.createdAt),
      updatedAt: this.convertTimestamp(row.updated_at || row.updatedAt),
      notes: row.notes || row.observacoes || '',
      customerName: row.customer_name || row.customerName || row.nomeCliente || ''
    };
  }

  /**
   * Converts items array
   */
  private convertItems(items: any[]): any[] {
    if (!Array.isArray(items)) return [];

    return items.map(item => ({
      id: item.id || '',
      productId: item.product_id || item.productId || item.produtoId || '',
      name: item.name || item.nome || '',
      quantity: item.quantity || item.quantidade || 0,
      unitPrice: item.unit_price || item.unitPrice || item.precoUnitario || 0,
      subtotal: item.subtotal || 0,
      notes: item.notes || item.observacoes || '',
      modifiers: item.modifiers || item.modificadores || []
    }));
  }

  /**
   * Converts timestamp (PostgreSQL or ISO string)
   */
  private convertTimestamp(timestamp: any): Date | null {
    if (!timestamp) return null;

    if (timestamp instanceof Date) {
      return timestamp;
    }

    if (typeof timestamp === 'string') {
      return new Date(timestamp);
    }

    if (typeof timestamp === 'number') {
      return new Date(timestamp);
    }

    return null;
  }

  /**
   * Calculates simple hash for shallow comparison
   */
  private calculateHash(row: any): string {
    // Uses key fields to detect changes
    const keyFields = [
      row.id,
      row.status,
      row.is_pago || row.isPago,
      row.updated_at || row.updatedAt || 0,
      row.items?.length || row.itens?.length || 0,
      row.total_amount || row.totalAmount || row.total || 0
    ];

    return keyFields.join(':');
  }

  /**
   * Detects changes between two rows (shallow comparison)
   */
  hasChanges(oldRow: any, newRow: any): boolean {
    const oldHash = this.calculateHash(oldRow);
    const newHash = this.calculateHash(newRow);

    return oldHash !== newHash;
  }

  /**
   * Converts only changed fields
   */
  convertChangedFields(
    oldRow: any,
    newRow: any,
    rowId: string
  ): Partial<any> {
    if (!this.hasChanges(oldRow, newRow)) {
      return {};
    }

    const changes: Partial<any> = {};

    // Check each field individually
    if (oldRow.status !== newRow.status) {
      changes.status = newRow.status;
    }

    const oldIsPago = oldRow.is_pago || oldRow.isPago;
    const newIsPago = newRow.is_pago || newRow.isPago;
    if (oldIsPago !== newIsPago) {
      changes.isPago = newIsPago;
    }

    const oldTotal = oldRow.total_amount || oldRow.totalAmount || oldRow.total;
    const newTotal = newRow.total_amount || newRow.totalAmount || newRow.total;
    if (oldTotal !== newTotal) {
      changes.totalAmount = newTotal;
    }

    const oldItems = JSON.stringify(oldRow.items || oldRow.itens);
    const newItems = JSON.stringify(newRow.items || newRow.itens);
    if (oldItems !== newItems) {
      changes.items = this.convertItems(newRow.items || newRow.itens || []);
    }

    const oldUpdated = oldRow.updated_at || oldRow.updatedAt;
    const newUpdated = newRow.updated_at || newRow.updatedAt;
    if (oldUpdated !== newUpdated) {
      changes.updatedAt = this.convertTimestamp(newUpdated);
    }

    return changes;
  }

  /**
   * Cleans expired cache
   */
  cleanExpiredCache(): void {
    const now = Date.now();

    for (const [key, cached] of this.cache.entries()) {
      if (now - cached.timestamp > this.CACHE_TTL) {
        this.cache.delete(key);
      }
    }
  }

  /**
   * Invalidates cache for a specific document
   */
  invalidateCache(rowId: string): void {
    this.cache.delete(`order:${rowId}`);
  }

  /**
   * Clears all cache
   */
  clearCache(): void {
    this.cache.clear();
  }

  /**
   * Gets cache statistics
   */
  getCacheStats() {
    return {
      size: this.cache.size,
      entries: Array.from(this.cache.keys())
    };
  }
}

// Singleton instance
export const supabaseConverter = new SupabaseConverter();

// Legacy export for compatibility
export const firestoreConverter = supabaseConverter;

// Export for tests
export { SupabaseConverter };
